SELECT MAX(`Free Meal Count (K-12)` / `Enrollment (K-12)`) AS highest_eligible_free_rate FROM frpm WHERE `County Name` = 'Alameda'   AND `Enrollment (K-12)` > 0;
SELECT      `Free Meal Count (Ages 5-17)` / `Enrollment (Ages 5-17)` AS eligible_free_rate FROM      frpm WHERE      `School Type` = 'Continuation'     AND `Enrollment (Ages 5-17)` > 0 ORDER BY      eligible_free_rate ASC LIMIT 3;
SELECT     s.Zip FROM schools AS s JOIN frpm AS f     ON s.CDSCode = f.CDSCode WHERE     f.`Charter School (Y/N)` = 1     AND s.District = 'Fresno County Office of Education';
SELECT     s.MailStreet FROM frpm f JOIN schools s     ON f.CDSCode = s.CDSCode ORDER BY     f.`FRPM Count (K-12)` DESC LIMIT 1;
SELECT DISTINCT s.Phone FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE f.`Charter School (Y/N)` = 1   AND f.`Charter Funding Type` = 'Directly funded'   AND s.OpenDate > '2000-01-01';
SELECT COUNT(*) AS school_count FROM satscores JOIN schools ON satscores.cds = schools.CDSCode WHERE satscores.AvgScrMath > 400   AND schools.Virtual = 'F';
SELECT DISTINCT s.School FROM schools s JOIN satscores st ON s.CDSCode = st.cds WHERE st.NumTstTakr > 500   AND s.Magnet = 1;
SELECT     s.Phone FROM schools AS s JOIN satscores AS ss     ON s.CDSCode = ss.cds ORDER BY     ss.NumGE1500 DESC LIMIT 1;
SELECT     s.NumTstTakr FROM satscores AS s JOIN frpm AS f     ON s.cds = f.CDSCode WHERE f.`FRPM Count (K-12)` = (     SELECT MAX(`FRPM Count (K-12)`)     FROM frpm );
SELECT COUNT(*) AS charter_funded_count FROM satscores s JOIN frpm f ON s.cds = f.CDSCode WHERE s.AvgScrMath > 560   AND f.`Charter Funding Type` = 'Directly funded';
SELECT     f."FRPM Count (Ages 5-17)" FROM satscores s JOIN frpm f   ON s.cds = f.CDSCode ORDER BY s.AvgScrRead DESC LIMIT 1;
SELECT     CDSCode FROM     frpm WHERE     (         COALESCE(`Enrollment (K-12)`, 0) + COALESCE(`Enrollment (Ages 5-17)`, 0)     ) > 500;
SELECT     MAX(f."Free Meal Count (Ages 5-17)" / f."Enrollment (Ages 5-17)") AS highest_eligible_free_rate FROM frpm f JOIN satscores s     ON f.CDSCode = s.cds WHERE s.NumTstTakr > 0   AND (s.NumGE1500 * 1.0 / s.NumTstTakr) > 0.3   AND f."Enrollment (Ages 5-17)" > 0;
SELECT     s.Phone FROM     schools s JOIN     satscores st ON s.CDSCode = st.cds ORDER BY     CAST(st.NumGE1500 AS REAL) / st.NumTstTakr DESC LIMIT 3;
SELECT     s.NCESSchool FROM frpm f JOIN schools s     ON f.CDSCode = s.CDSCode ORDER BY     f.`Enrollment (Ages 5-17)` DESC LIMIT 5;
SELECT     s.District FROM schools s JOIN satscores st ON s.CDSCode = st.cds WHERE s.StatusType = 'Active' GROUP BY s.District ORDER BY AVG(st.AvgScrRead) DESC LIMIT 1;
SELECT COUNT(*) FROM satscores WHERE dname = 'Alameda'   AND NumTstTakr < 100;
SELECT     s.CDSCode,     s.School,     s.CharterNum,     AVG(ss.AvgScrWrite) AS AvgWritingScore FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE ss.AvgScrWrite > 499   AND s.CharterNum IS NOT NULL GROUP BY s.CDSCode, s.School, s.CharterNum ORDER BY AvgWritingScore DESC;
SELECT     COUNT(*) FROM satscores AS s JOIN schools AS sc     ON s.cds = sc.CDSCode WHERE     sc.County = 'Fresno'     AND sc.FundingType = 'Directly funded'     AND s.NumTstTakr <= 250;
SELECT s.Phone FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds ORDER BY sat.AvgScrMath DESC LIMIT 1;
SELECT COUNT(*) AS school_count FROM frpm WHERE "County Name" = 'Amador'   AND "Low Grade" = '9'   AND "High Grade" = '12';
SELECT     COUNT(*) AS school_count FROM     frpm WHERE     frpm.`County Name` = 'Los Angeles'     AND frpm.`Free Meal Count (K-12)` > 500     AND frpm.`FRPM Count (K-12)` < 700;
SELECT     s.School FROM schools s JOIN satscores st ON s.CDSCode = st.cds WHERE s.County = 'Contra Costa' ORDER BY st.NumTstTakr DESC LIMIT 1;
SELECT     frpm.`School Name` AS school_name,     schools.`Street` AS street_address FROM frpm JOIN schools     ON frpm.`CDSCode` = schools.`CDSCode` WHERE     frpm.`Enrollment (K-12)` IS NOT NULL     AND frpm.`Enrollment (Ages 5-17)` IS NOT NULL     AND (frpm.`Enrollment (K-12)` - frpm.`Enrollment (Ages 5-17)`) > 30;
SELECT DISTINCT s.School FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode JOIN satscores sat ON s.CDSCode = sat.cds WHERE f.`Enrollment (K-12)` > 0   AND (f.`Free Meal Count (K-12)` / f.`Enrollment (K-12)`) > 0.1   AND sat.NumGE1500 > 0;
SELECT     s.FundingType FROM schools s JOIN satscores sat     ON s.CDSCode = sat.cds WHERE     s.County = 'Riverside' GROUP BY     s.FundingType HAVING     SUM(sat.AvgScrMath) / COUNT(sat.cds) > 400;
SELECT     s.School AS name,     s.Street || ', ' || s.City || ', ' || s.State || ' ' || s.Zip AS full_communication_address FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE     s.County = 'Monterey'     AND f.School Type = 'High'     AND f."Free Meal Count (Ages 5-17)" > 800;
SELECT     s.School AS school_name,     ss.AvgScrWrite AS writing_score,     s.Phone AS communication_number FROM schools s JOIN satscores ss     ON s.CDSCode = ss.cds WHERE     (s.OpenDate > '1991-12-31')     OR     (s.ClosedDate < '2000-01-01');
WITH avg_diff AS (     SELECT AVG(`Enrollment (K-12)` - `Enrollment (Ages 5-17)`) AS avg_difference     FROM frpm     WHERE `Charter Funding Type` = 'Locally funded' ), school_diff AS (     SELECT          s.`School` AS school_name,         s.`DOCType` AS doc_type,         (f.`Enrollment (K-12)` - f.`Enrollment (Ages 5-17)`) AS difference     FROM frpm f     JOIN schools s ON f.`CDSCode` = s.`CDSCode`     WHERE f.`Charter Funding Type` = 'Locally funded' ) SELECT      sd.school_name,     sd.doc_type FROM school_diff sd CROSS JOIN avg_diff ad WHERE sd.difference > ad.avg_difference;
SELECT     s.OpenDate FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE f.`Low Grade` = 'K'   AND f.`High Grade` = '12' ORDER BY f.`Enrollment (K-12)` DESC LIMIT 1;
SELECT      s.City FROM      schools s JOIN      frpm f ON s.CDSCode = f.CDSCode WHERE      f.`Enrollment (K-12)` IS NOT NULL ORDER BY      f.`Enrollment (K-12)` ASC LIMIT 5;
WITH RankedSchools AS (     SELECT          CDSCode,         "Free Meal Count (K-12)" / "Enrollment (K-12)" AS EligibleFreeRate,         ROW_NUMBER() OVER (ORDER BY "Enrollment (K-12)" DESC) AS Rank     FROM frpm     WHERE "Enrollment (K-12)" IS NOT NULL       AND "Free Meal Count (K-12)" IS NOT NULL ) SELECT EligibleFreeRate FROM RankedSchools WHERE Rank IN (10, 11) ORDER BY Rank;
SELECT      f."FRPM Count (K-12)" / f."Enrollment (K-12)" AS eligible_free_or_reduced_price_meal_rate FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE s.DOC = '66'   AND f."Low Grade" = 'K'   AND f."High Grade" = '12' ORDER BY f."FRPM Count (K-12)" DESC LIMIT 5;
SELECT     s.Website,     s.School FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE f.`Free Meal Count (Ages 5-17)` BETWEEN 1900 AND 2000;
SELECT     f."Free Meal Count (Ages 5-17)" / f."Enrollment (Ages 5-17)" AS free_rate FROM frpm AS f JOIN schools AS s   ON f.CDSCode = s.CDSCode WHERE     s.AdmFName1 = 'Kacey' AND s.AdmLName1 = 'Gibson'     OR s.AdmFName2 = 'Kacey' AND s.AdmLName2 = 'Gibson'     OR s.AdmFName3 = 'Kacey' AND s.AdmLName3 = 'Gibson';
SELECT     s.AdmEmail1 FROM frpm AS f JOIN schools AS s     ON f.CDSCode = s.CDSCode WHERE     f.`Charter School (Y/N)` = 1 ORDER BY     f.`Enrollment (K-12)` ASC LIMIT 1;
WITH top_school AS (     SELECT          s.CDSCode,         s.AdmFName1,         s.AdmLName1,         s.AdmFName2,         s.AdmLName2,         s.AdmFName3,         s.AdmLName3     FROM schools s     JOIN satscores sat ON s.CDSCode = sat.cds     ORDER BY sat.NumGE1500 DESC     LIMIT 1 ) SELECT      CASE WHEN AdmFName1 IS NOT NULL AND AdmLName1 IS NOT NULL THEN AdmFName1 || ' ' || AdmLName1 ELSE NULL END AS admin1,     CASE WHEN AdmFName2 IS NOT NULL AND AdmLName2 IS NOT NULL THEN AdmFName2 || ' ' || AdmLName2 ELSE NULL END AS admin2,     CASE WHEN AdmFName3 IS NOT NULL AND AdmLName3 IS NOT NULL THEN AdmFName3 || ' ' || AdmLName3 ELSE NULL END AS admin3 FROM top_school;
SELECT      s.Street,     s.City,     s.Zip,     s.State FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE ss.NumTstTakr > 0 ORDER BY (ss.NumGE1500 * 1.0 / ss.NumTstTakr) ASC LIMIT 1;
SELECT s.Website FROM schools s JOIN satscores st ON s.CDSCode = st.cds WHERE s.County = 'Los Angeles'   AND st.NumTstTakr BETWEEN 2000 AND 3000;
SELECT     AVG(s.NumTstTakr) AS average_test_takers FROM satscores AS s JOIN schools AS sc     ON s.cds = sc.CDSCode WHERE     sc.County = 'Fresno'     AND sc.OpenDate BETWEEN '1980-01-01' AND '1980-12-31';
SELECT     s.Phone FROM schools AS s JOIN satscores AS ss     ON s.CDSCode = ss.cds WHERE     s.District = 'Fresno Unified' ORDER BY     ss.AvgScrRead ASC LIMIT 1;
WITH VirtualSchools AS (     SELECT          s.CDSCode,         s.School,         s.County,         sa.AvgScrRead     FROM schools s     JOIN satscores sa ON s.CDSCode = sa.cds     WHERE s.Virtual = 'F' ), RankedSchools AS (     SELECT          CDSCode,         School,         County,         AvgScrRead,         RANK() OVER (PARTITION BY County ORDER BY AvgScrRead DESC) AS rank_in_county     FROM VirtualSchools ) SELECT School FROM RankedSchools WHERE rank_in_county <= 5;
SELECT     s.EdOpsName FROM satscores AS sat JOIN schools AS s     ON sat.cds = s.CDSCode ORDER BY     sat.AvgScrMath DESC LIMIT 1;
WITH RankedSchools AS (     SELECT         s.cds,         s.AvgScrMath,         s.AvgScrRead,         s.AvgScrWrite,         (s.AvgScrMath + s.AvgScrRead + s.AvgScrWrite) AS TotalScore,         sc.County     FROM satscores s     JOIN schools sc ON s.cds = sc.CDSCode     WHERE s.AvgScrMath IS NOT NULL       AND s.AvgScrRead IS NOT NULL       AND s.AvgScrWrite IS NOT NULL ), LowestScoreSchool AS (     SELECT         cds,         AvgScrMath,         County     FROM RankedSchools     ORDER BY TotalScore ASC     LIMIT 1 ) SELECT     AvgScrMath AS AverageMathScore,     County FROM LowestScoreSchool;
WITH ranked_schools AS (     SELECT         s.cds,         s.AvgScrWrite,         s.NumGE1500,         sc.City,         ROW_NUMBER() OVER (ORDER BY s.NumGE1500 DESC) AS rn     FROM satscores s     JOIN schools sc ON s.cds = sc.CDSCode     WHERE s.NumGE1500 IS NOT NULL ) SELECT     AVG(r.AvgScrWrite) AS avg_writing_score,     r.City FROM ranked_schools r WHERE r.rn = 1;
SELECT     s.School,     AVG(ss.AvgScrWrite) AS AvgWritingScore FROM schools s JOIN satscores ss     ON s.CDSCode = ss.cds WHERE     s.AdmLName1 = 'Ulrich' AND s.AdmFName1 = 'Ricci'     OR s.AdmLName2 = 'Ulrich' AND s.AdmFName2 = 'Ricci'     OR s.AdmLName3 = 'Ulrich' AND s.AdmFName3 = 'Ricci' GROUP BY s.School;
SELECT     s.School FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE     s.DOC = '31' ORDER BY     f.`Enrollment (K-12)` DESC LIMIT 1;
SELECT   COUNT(*) / 12.0 AS monthly_average FROM   schools WHERE   County = 'Alameda'   AND DOC = '52'   AND OpenDate LIKE '1980-%';
SELECT      CAST(SUM(CASE WHEN s.DOC = '54' THEN 1 ELSE 0 END) AS REAL) * 1.0 /      NULLIF(SUM(CASE WHEN s.DOC = '52' THEN 1 ELSE 0 END), 0) AS ratio FROM schools s WHERE s.County = 'Orange'   AND s.StatusType = 'Merged'   AND s.DOC IN ('52', '54');
WITH ClosedSchools AS (     SELECT          s.County,         s.School,         s.ClosedDate     FROM schools s     WHERE s.StatusType = 'Closed' ), CountyCounts AS (     SELECT          County,         COUNT(*) AS ClosedSchoolCount     FROM ClosedSchools     GROUP BY County ), TopCounty AS (     SELECT          County     FROM CountyCounts     ORDER BY ClosedSchoolCount DESC     LIMIT 1 ) SELECT      cs.School,     cs.ClosedDate FROM ClosedSchools cs JOIN TopCounty tc ON cs.County = tc.County ORDER BY cs.ClosedDate;
WITH RankedSchools AS (     SELECT          s.CDSCode,         s.School,         s.MailStreet,         sats.AvgScrMath,         RANK() OVER (ORDER BY sats.AvgScrMath DESC) AS math_rank     FROM satscores sats     JOIN schools s ON sats.cds = s.CDSCode     WHERE sats.AvgScrMath IS NOT NULL ) SELECT      rs.School,     rs.MailStreet FROM RankedSchools rs WHERE rs.math_rank = 7 LIMIT 1;
SELECT     s.MailStreet,     s.School FROM schools s JOIN satscores st ON s.CDSCode = st.cds ORDER BY st.AvgScrRead ASC LIMIT 1;
SELECT     COUNT(*) FROM satscores AS s JOIN schools AS sc     ON s.cds = sc.CDSCode WHERE     sc.MailCity = 'Lakeport'     AND (s.AvgScrRead + s.AvgScrMath + s.AvgScrWrite) >= 1500;
SELECT     SUM(s.NumTstTakr) FROM satscores AS s JOIN schools AS sc     ON s.cds = sc.CDSCode WHERE sc.MailCity = 'Fresno';
SELECT     s.School,     s.MailZip FROM     schools AS s WHERE     s.AdmFName1 = 'Avetik'     AND s.AdmLName1 = 'Atoian';
SELECT      CAST(SUM(CASE WHEN s.County = 'Colusa' THEN 1 ELSE 0 END) AS REAL) /      NULLIF(SUM(CASE WHEN s.County = 'Humboldt' THEN 1 ELSE 0 END), 0) AS ratio FROM schools s WHERE s.MailState = 'CA';
SELECT COUNT(*) FROM schools WHERE MailState = 'CA'   AND City = 'San Joaquin'   AND StatusType = 'Active';
SELECT     s.Phone,     s.Ext FROM schools s JOIN satscores sat     ON s.CDSCode = sat.cds ORDER BY     sat.AvgScrWrite DESC LIMIT 1 OFFSET 332;
SELECT      s.Phone,     s.Ext,     s.School FROM schools s WHERE s.Zip = '95203-3704';
SELECT DISTINCT s.Website FROM schools s WHERE (s.AdmFName1 = 'Mike' AND s.AdmLName1 = 'Larson')    OR (s.AdmFName2 = 'Mike' AND s.AdmLName2 = 'Larson')    OR (s.AdmFName3 = 'Mike' AND s.AdmLName3 = 'Larson')    OR (s.AdmFName1 = 'Dante' AND s.AdmLName1 = 'Alvarez')    OR (s.AdmFName2 = 'Dante' AND s.AdmLName2 = 'Alvarez')    OR (s.AdmFName3 = 'Dante' AND s.AdmLName3 = 'Alvarez');
SELECT     s.Website FROM     schools AS s WHERE     s.Virtual = 'P'     AND s.Charter = 1     AND s.County = 'San Joaquin';
SELECT COUNT(*) AS chartered_schools_count FROM schools WHERE City = 'Hickman'   AND Charter = 1   AND DOC = '52';
SELECT COUNT(*) AS total_non_chartered_schools FROM frpm WHERE `County Name` = 'Los Angeles'   AND `Charter School (Y/N)` = 0   AND `Enrollment (K-12)` > 0   AND (`Free Meal Count (K-12)` * 100.0 / `Enrollment (K-12)`) < 0.18;
SELECT     s.School AS school_name,     s.City AS city,     s.AdmFName1 || ' ' || s.AdmLName1 AS administrator_1,     s.AdmFName2 || ' ' || s.AdmLName2 AS administrator_2,     s.AdmFName3 || ' ' || s.AdmLName3 AS administrator_3 FROM schools s WHERE s.Charter = 1   AND s.CharterNum = '00D2';
SELECT COUNT(*) AS total_schools FROM schools WHERE MailCity = 'Hickman'   AND CharterNum = '00D4';
SELECT     CAST(COUNT(CASE WHEN s.FundingType = 'Locally Funded' THEN 1 END) AS REAL) * 100 / COUNT(*) FROM schools s WHERE s.County = 'Santa Clara'   AND s.FundingType IS NOT NULL;
SELECT COUNT(*) AS directly_funded_schools_count FROM schools WHERE County = 'Stanislaus'   AND FundingType = 'Directly Funded'   AND OpenDate BETWEEN '2000-01-01' AND '2005-12-31';
SELECT     COUNT(*) AS total_closure_count FROM schools WHERE     DOCType = 'Community College District'     AND ClosedDate LIKE '1989%'     AND City = 'San Francisco';
SELECT     s.County FROM     schools s WHERE     s.SOC = '11'     AND s.ClosedDate IS NOT NULL     AND s.ClosedDate >= '1980-01-01'     AND s.ClosedDate < '1990-01-01' GROUP BY     s.County ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT     s.NCESDist FROM     schools AS s WHERE     s.SOC = '31';
SELECT COUNT(*) FROM schools WHERE County = 'Alpine'   AND DOCType = 'District Community Day School'   AND StatusType IN ('Active', 'Closed');
SELECT     s.District FROM schools AS s WHERE     s.City = 'Fresno'     AND s.Magnet = 0;
SELECT     f."Enrollment (Ages 5-17)" FROM frpm AS f JOIN schools AS s     ON f.CDSCode = s.CDSCode WHERE     s."EdOpsCode" = 'SSS'     AND s."City" = 'Fremont'     AND f."Academic Year" = '2014-2015';
SELECT     f."FRPM Count (Ages 5-17)" FROM frpm AS f JOIN schools AS s     ON f.CDSCode = s.CDSCode WHERE     s.School = 'Youth Authority School'     AND s.MailStreet = 'PO Box 1040';
SELECT     frpm."Low Grade" FROM frpm JOIN schools     ON frpm.CDSCode = schools.CDSCode WHERE     schools.NCESSchool = '0613360'     AND schools.EdOpsCode = 'SPECON';
SELECT     s.School,     s.EdOpsName FROM schools AS s JOIN frpm AS f   ON s.CDSCode = f.CDSCode WHERE f.`NSLP Provision Status` = 'Breakfast Provision 2'   AND f.`County Code` = '37';
SELECT     s.City FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE     s.EILCode = 'HS'     AND f.`NSLP Provision Status` = '2'     AND f.`Low Grade` = '9'     AND f.`High Grade` = '12'     AND f.`County Name` = 'Merced';
SELECT     s.School,     (f.`FRPM Count (Ages 5-17)` / f.`Enrollment (Ages 5-17)` * 100) AS `Percent (%) Eligible FRPM (Ages 5-17)` FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.County = 'Los Angeles'   AND s.GSserved LIKE '%K%'   AND s.GSserved LIKE '%9%'   AND f.`Enrollment (Ages 5-17)` IS NOT NULL   AND f.`Enrollment (Ages 5-17)` != 0;
SELECT     s.GSserved FROM schools AS s WHERE s.City = 'Adelanto' GROUP BY     s.GSserved ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT      CASE          WHEN s.County = 'San Diego' THEN 'San Diego'         WHEN s.County = 'Santa Barbara' THEN 'Santa Barbara'     END AS County,     COUNT(*) AS SchoolCount FROM      schools s WHERE      s.County IN ('San Diego', 'Santa Barbara')     AND s.Virtual = 'F' GROUP BY      s.County ORDER BY      SchoolCount DESC LIMIT 1;
SELECT     s.School,     s.Latitude,     f.School_Type FROM schools s JOIN frpm f   ON s.CDSCode = f.CDSCode ORDER BY s.Latitude DESC LIMIT 1;
SELECT     s.City,     f."Low Grade",     s.School FROM schools s JOIN frpm f   ON s.CDSCode = f.CDSCode WHERE s.State = 'CA' ORDER BY s.Latitude ASC LIMIT 1;
SELECT     s.GSoffered FROM     schools s ORDER BY     ABS(s.Longitude) DESC LIMIT 1;
SELECT     s.City,     COUNT(*) AS num_schools FROM schools s JOIN frpm f   ON s.CDSCode = f.CDSCode WHERE s.Magnet = 1   AND s.GSserved = 'K-8'   AND f.`NSLP Provision Status` = 'Multiple Provision Types' GROUP BY s.City;
WITH admin_names AS (     SELECT         s.District,         s.AdmFName1 AS first_name     FROM schools s     WHERE s.AdmFName1 IS NOT NULL AND s.AdmFName1 <> ''     UNION ALL     SELECT         s.District,         s.AdmFName2 AS first_name     FROM schools s     WHERE s.AdmFName2 IS NOT NULL AND s.AdmFName2 <> ''     UNION ALL     SELECT         s.District,         s.AdmFName3 AS first_name     FROM schools s     WHERE s.AdmFName3 IS NOT NULL AND s.AdmFName3 <> '' ), name_counts AS (     SELECT         first_name,         COUNT(*) AS cnt     FROM admin_names     GROUP BY first_name ), top_two AS (     SELECT         first_name,         cnt,         ROW_NUMBER() OVER (ORDER BY cnt DESC, first_name ASC) AS rn     FROM name_counts ) SELECT     t.first_name,     a.District FROM top_two t JOIN admin_names a   ON a.first_name = t.first_name WHERE t.rn <= 2 ORDER BY t.cnt DESC, t.first_name ASC, a.District ASC;
SELECT      f."District Code",     (f."Free Meal Count (K-12)" / f."Enrollment (K-12)") * 100 AS "Percent (%) Eligible Free (K-12)" FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE s."AdmFName1" = 'Alusine'   AND f."Enrollment (K-12)" IS NOT NULL   AND f."Enrollment (K-12)" != 0;
SELECT     s.AdmLName1 AS administrator_last_name,     s.District AS district,     s.County AS county,     s.School AS school_name FROM schools s WHERE s.CharterNum = '40';
SELECT     s.AdmEmail1 FROM     schools s WHERE     s.County = 'San Bernardino'     AND s.District = 'San Bernardino City Unified'     AND s.OpenDate BETWEEN '2009-01-01' AND '2010-12-31'     AND s.SOC = '62'     AND s.DOC = '54'     AND s.AdmEmail1 IS NOT NULL     AND s.AdmEmail1 LIKE '%@%';
SELECT     s.AdmEmail1,     s.School FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds ORDER BY sat.NumGE1500 DESC LIMIT 1;
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE a.frequency = 'POPLATEK PO OBRATU'   AND d.A3 = 'East Bohemia';
SELECT COUNT(DISTINCT a.account_id) FROM account a JOIN district d ON a.district_id = d.district_id JOIN loan l ON a.account_id = l.account_id WHERE d.A3 = 'Prague';
SELECT      CASE          WHEN AVG(A12) > AVG(A13) THEN '1995'         ELSE '1996'     END AS higher_unemployment_year FROM district;
SELECT COUNT(DISTINCT d.district_id) FROM district d JOIN client c ON d.district_id = c.district_id WHERE c.gender = 'F'   AND d.A11 > 6000   AND d.A11 < 10000;
SELECT COUNT(*) AS count FROM client c JOIN district d   ON c.district_id = d.district_id WHERE c.gender = 'M'   AND d.A3 = 'North Bohemia'   AND d.A11 > 8000;
WITH client_district AS (     SELECT          c.client_id,         c.gender,         c.birth_date,         d.A11 AS avg_salary     FROM client c     JOIN district d ON c.district_id = d.district_id     WHERE c.gender = 'F' ), ranked_clients AS (     SELECT          cd.*,         ROW_NUMBER() OVER (ORDER BY cd.birth_date ASC, cd.avg_salary ASC) AS rn     FROM client_district cd ), oldest_lowest AS (     SELECT          avg_salary AS lowest_avg_salary     FROM ranked_clients     WHERE rn = 1 ), highest_salary AS (     SELECT          MAX(avg_salary) AS highest_avg_salary     FROM client_district ) SELECT      a.account_id,     (hs.highest_avg_salary - ol.lowest_avg_salary) AS gap FROM account a JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id JOIN client_district cd ON c.client_id = cd.client_id JOIN ranked_clients rc ON cd.client_id = rc.client_id JOIN oldest_lowest ol ON 1=1 JOIN highest_salary hs ON 1=1 WHERE rc.rn = 1;
SELECT     c.client_id FROM     client c JOIN     district d     ON c.district_id = d.district_id ORDER BY     c.birth_date DESC,     d.A11 DESC LIMIT 1;
SELECT COUNT(*) AS owner_count FROM disp d JOIN account a ON d.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE'   AND d.type = 'OWNER';
SELECT     c.client_id FROM client AS c JOIN disp AS d     ON c.client_id = d.client_id JOIN account AS a     ON d.account_id = a.account_id JOIN trans AS t     ON a.account_id = t.account_id WHERE     d.type = 'DISPONENT'     AND a.frequency = 'POPLATEK PO OBRATU';
SELECT     a.account_id FROM     account a JOIN     loan l     ON a.account_id = l.account_id WHERE     l.status = 'A'     AND strftime('%Y', l.date) = '1997'     AND a.frequency = 'POPLATEK TYDNE' ORDER BY     l.amount ASC LIMIT 1;
SELECT     a.account_id FROM account AS a JOIN loan AS l     ON a.account_id = l.account_id WHERE     l.duration > 12     AND a.date LIKE '1993%'     AND l.amount = (         SELECT MAX(l2.amount)         FROM loan AS l2         JOIN account AS a2             ON l2.account_id = a2.account_id         WHERE             l2.duration > 12             AND a2.date LIKE '1993%'     );
SELECT COUNT(*) FROM client c JOIN district d ON c.district_id = d.district_id JOIN disp dp ON c.client_id = dp.client_id JOIN account a ON dp.account_id = a.account_id WHERE c.gender = 'F'   AND c.birth_date < '1950-01-01'   AND d.A2 = 'Sokolov';
SELECT     a.account_id FROM account AS a JOIN trans AS t     ON a.account_id = t.account_id WHERE     strftime('%Y', t.date) = '1995'     AND t.date = (         SELECT MIN(t2.date)         FROM trans AS t2         WHERE strftime('%Y', t2.date) = '1995'     );
SELECT DISTINCT a.account_id FROM account a JOIN trans t ON a.account_id = t.account_id WHERE a.date < '1997-01-01'   AND t.amount > 3000;
SELECT     c.client_id FROM client AS c JOIN disp AS d     ON c.client_id = d.client_id JOIN card AS cd     ON d.disp_id = cd.disp_id WHERE     cd.issued = '1994-03-03';
SELECT a.date FROM trans t JOIN account a ON t.account_id = a.account_id WHERE t.amount = 840   AND t.date = '1998-10-14';
SELECT     a.district_id FROM loan AS l JOIN account AS a   ON l.account_id = a.account_id WHERE     l.date = '1994-08-25';
SELECT     MAX(t.amount) AS biggest_amount FROM trans t JOIN disp d     ON t.account_id = d.account_id JOIN card c     ON d.disp_id = c.disp_id WHERE     c.issued = '1996-10-21';
WITH highest_avg_salary_district AS (     SELECT          district_id     FROM          district     ORDER BY          A11 DESC     LIMIT 1 ) SELECT      c.gender FROM      client c JOIN      disp d ON c.client_id = d.client_id JOIN      account a ON d.account_id = a.account_id JOIN      highest_avg_salary_district h ON a.district_id = h.district_id ORDER BY      c.birth_date ASC LIMIT 1;
WITH client_loans AS (     SELECT         c.client_id,         c.birth_date,         l.loan_id,         l.amount AS loan_amount,         a.date AS account_open_date     FROM client c     JOIN disp d ON c.client_id = d.client_id     JOIN account a ON d.account_id = a.account_id     JOIN loan l ON a.account_id = l.account_id ), biggest_loan_client AS (     SELECT         client_id,         birth_date,         account_open_date,         loan_amount,         ROW_NUMBER() OVER (ORDER BY loan_amount DESC) AS rn     FROM client_loans ), first_transaction AS (     SELECT         t.trans_id,         t.account_id,         t.date,         t.amount,         ROW_NUMBER() OVER (PARTITION BY t.account_id ORDER BY t.date ASC, t.trans_id ASC) AS rn     FROM trans t ) SELECT     ft.amount FROM biggest_loan_client blc JOIN client_loans cl ON blc.client_id = cl.client_id AND blc.loan_id = cl.loan_id JOIN disp d ON cl.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN first_transaction ft ON a.account_id = ft.account_id AND ft.rn = 1 WHERE blc.rn = 1 LIMIT 1;
SELECT COUNT(DISTINCT c.client_id) AS female_client_count FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dt ON a.district_id = dt.district_id WHERE dt.A2 = 'Jesenik'   AND c.gender = 'F';
SELECT d.disp_id FROM disp d JOIN client c ON d.client_id = c.client_id JOIN trans t ON d.account_id = t.account_id WHERE t.amount = 5100   AND t.date = '1998-09-02';
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Litomerice'   AND strftime('%Y', a.date) = '1996';
SELECT d.A2 FROM client c JOIN disp dp ON c.client_id = dp.client_id JOIN account a ON dp.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE c.gender = 'F'   AND c.birth_date = '1976-01-29';
SELECT c.birth_date FROM client c JOIN disp d ON c.client_id = d.client_id JOIN loan l ON d.account_id = l.account_id WHERE l.amount = 98832   AND l.date = '1996-01-03';
SELECT a.account_id FROM account a JOIN district d ON a.district_id = d.district_id JOIN disp dp ON a.account_id = dp.account_id JOIN client c ON dp.client_id = c.client_id WHERE d.A3 = 'Prague' ORDER BY a.date ASC LIMIT 1;
WITH south_bohemia_districts AS (     SELECT          d.district_id,         d.A4 AS inhabitants,         c.client_id,         c.gender     FROM district d     JOIN client c ON d.district_id = c.district_id     WHERE d.A3 = 'south Bohemia' ), max_inhabitants AS (     SELECT MAX(inhabitants) AS max_inhabitants     FROM south_bohemia_districts ), target_district AS (     SELECT          s.district_id,         s.client_id,         s.gender     FROM south_bohemia_districts s     JOIN max_inhabitants m ON s.inhabitants = m.max_inhabitants ) SELECT      CAST(SUM(CASE WHEN gender = 'M' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(client_id) AS percentage_male FROM target_district;
WITH first_loan AS (     SELECT         l.account_id     FROM loan l     WHERE l.date = '1993-07-05'     ORDER BY l.date ASC     LIMIT 1 ), balances AS (     SELECT         t.account_id,         t.date,         t.balance     FROM trans t     WHERE t.date IN ('1993-03-22', '1998-12-27') ) SELECT     (MAX(CASE WHEN b.date = '1998-12-27' THEN b.balance END) -      MAX(CASE WHEN b.date = '1993-03-22' THEN b.balance END)) * 100.0 /     MAX(CASE WHEN b.date = '1993-03-22' THEN b.balance END) AS increase_rate FROM balances b JOIN first_loan fl ON b.account_id = fl.account_id;
SELECT      (SUM(CASE WHEN status = 'A' THEN amount ELSE 0 END) * 100.0) / SUM(amount) AS percentage FROM loan;
SELECT      CAST(SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) AS REAL) * 100 / SUM(amount) AS percentage FROM loan WHERE amount < 100000;
SELECT     a.account_id,     d.A2 AS district_name,     d.A3 AS district_region FROM account a JOIN district d     ON a.district_id = d.district_id WHERE     a.frequency = 'POPLATEK PO OBRATU'     AND strftime('%Y', a.date) = '1993';
SELECT DISTINCT     a.account_id,     a.frequency FROM account a JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id JOIN district dist ON c.district_id = dist.district_id WHERE d.type = 'OWNER'   AND dist.A3 = 'east Bohemia'   AND a.date >= '1995-01-01'   AND a.date < '2001-01-01';
SELECT     a.account_id,     a.date FROM account AS a JOIN district AS d     ON a.district_id = d.district_id WHERE d.A2 = 'Prachatice';
SELECT d.A2 AS district, d.A3 AS region FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.loan_id = 4990;
SELECT     l.account_id,     d.A2 AS district,     d.A3 AS region FROM loan AS l JOIN account AS a     ON l.account_id = a.account_id JOIN district AS d     ON a.district_id = d.district_id WHERE l.amount > 300000;
SELECT     l.loan_id,     d.A3 AS district,     d.A11 AS average_salary FROM loan l JOIN account a     ON l.account_id = a.account_id JOIN district d     ON a.district_id = d.district_id WHERE     l.duration = 60;
SELECT     d.A2 AS district,     ((d.A13 - d.A12) / d.A12) * 100 AS unemployment_increment_rate FROM loan l JOIN account a     ON l.account_id = a.account_id JOIN district d     ON a.district_id = d.district_id WHERE l.status = 'D';
SELECT   CAST(SUM(CASE WHEN a.date LIKE '1993-%' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM account a JOIN district d   ON a.district_id = d.district_id WHERE d.A2 = 'Decin';
SELECT account_id FROM account WHERE frequency = 'POPLATEK MESICNE';
SELECT     d.A2,     COUNT(c.client_id) AS female_account_holders FROM district d JOIN client c     ON d.district_id = c.district_id JOIN disp dp     ON c.client_id = dp.client_id JOIN account a     ON dp.account_id = a.account_id WHERE c.gender = 'F' GROUP BY d.A2 ORDER BY female_account_holders DESC LIMIT 9;
SELECT     d.A2 AS district_name,     t.amount FROM trans t JOIN account a     ON t.account_id = a.account_id JOIN district d     ON a.district_id = d.district_id WHERE     t.type = 'VYDAJ'     AND t.date LIKE '1996-01%' ORDER BY     t.amount DESC LIMIT 10;
SELECT COUNT(*) FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A3 = 'South Bohemia'   AND NOT EXISTS (     SELECT 1     FROM disp dp     JOIN card c ON dp.disp_id = c.disp_id     WHERE dp.account_id = a.account_id       AND dp.type = 'OWNER'   );
SELECT d.A3 FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.status IN ('C', 'D') ORDER BY l.amount DESC LIMIT 1;
SELECT AVG(l.amount) AS average_loan_amount FROM loan l JOIN account a ON l.account_id = a.account_id JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE c.gender = 'M';
SELECT     d.A4 AS branch_location,     d.A2 AS district_name FROM district AS d WHERE d.A13 = (     SELECT MAX(d2.A13)     FROM district AS d2 );
SELECT COUNT(a.account_id) AS num_accounts FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A16 = (     SELECT MAX(A16)     FROM district );
SELECT COUNT(DISTINCT t.account_id) AS account_count FROM trans t JOIN account a ON t.account_id = a.account_id WHERE t.operation = 'VYBER KARTOU'   AND t.balance < 0   AND a.frequency = 'POPLATEK MESICNE';
SELECT COUNT(*) AS loan_count FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.date BETWEEN '1995-01-01' AND '1997-12-31'   AND l.amount >= 250000   AND a.frequency = 'POPLATEK MESICNE';
SELECT COUNT(*) AS account_count FROM loan WHERE status IN ('C', 'D')   AND account_id IN (     SELECT account_id     FROM account     WHERE district_id = 1   );
WITH district_crimes AS (     SELECT          d.district_id,         d.A15 AS crimes_1995     FROM district d     WHERE d.A15 IS NOT NULL ), ranked_districts AS (     SELECT          district_id,         crimes_1995,         DENSE_RANK() OVER (ORDER BY crimes_1995 DESC) AS rank     FROM district_crimes ), target_district AS (     SELECT district_id     FROM ranked_districts     WHERE rank = 2     LIMIT 1 ) SELECT COUNT(c.client_id) AS male_client_count FROM client c JOIN target_district td ON c.district_id = td.district_id WHERE c.gender = 'M';
SELECT COUNT(*) FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE c.type = 'gold'   AND d.type = 'OWNER';
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Pisek';
SELECT DISTINCT d.district_id FROM district d JOIN account a ON d.district_id = a.district_id JOIN trans t ON a.account_id = t.account_id WHERE t.amount > 10000   AND strftime('%Y', t.date) = '1997';
SELECT DISTINCT o.account_id FROM `order` o JOIN account a ON o.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE o.k_symbol = 'SIPO'   AND d.A2 = 'Pisek';
SELECT DISTINCT a.account_id FROM account a JOIN disp d ON a.account_id = d.account_id JOIN card c ON d.disp_id = c.disp_id WHERE c.type = 'gold';
SELECT AVG(t.amount) AS average_amount FROM trans t JOIN account a ON t.account_id = a.account_id WHERE t.operation = 'VYBER KARTOU'   AND strftime('%Y', t.date) = '2021'   AND a.frequency = 'POPLATEK MESICNE';
SELECT     d.client_id FROM trans t JOIN disp d   ON t.account_id = d.account_id WHERE t.operation = 'VYBER KARTOU'   AND strftime('%Y', t.date) = '1998'   AND t.amount < (       SELECT AVG(amount)       FROM trans       WHERE operation = 'VYBER KARTOU'         AND strftime('%Y', date) = '1998'   );
SELECT DISTINCT c.client_id FROM client c JOIN disp d   ON c.client_id = d.client_id  AND d.type = 'OWNER' JOIN card cd   ON d.disp_id = cd.disp_id JOIN loan l   ON d.account_id = l.account_id WHERE c.gender = 'F';
SELECT COUNT(DISTINCT c.client_id) AS female_clients_in_south_bohemia FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE c.gender = 'F'   AND dist.A3 LIKE '%south Bohemia%';
SELECT DISTINCT a.account_id FROM account a JOIN district d ON a.district_id = d.district_id JOIN disp dp ON a.account_id = dp.account_id WHERE d.A2 = 'Tabor'   AND dp.type = 'OWNER';
SELECT DISTINCT     d.type AS account_type,     dist.A11 AS average_income FROM disp d JOIN account a     ON d.account_id = a.account_id JOIN district dist     ON a.district_id = dist.district_id WHERE d.type <> 'OWNER'   AND dist.A11 > 8000   AND dist.A11 <= 9000;
SELECT COUNT(DISTINCT t.account_id) AS account_count FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE d.A3 = 'North Bohemia'   AND t.bank = 'AB';
SELECT DISTINCT d.A2 FROM district d JOIN account a ON d.district_id = a.district_id JOIN trans t ON a.account_id = t.account_id WHERE t.type = 'VYDAJ';
SELECT AVG(d.A15) FROM district d JOIN account a ON d.district_id = a.district_id WHERE d.A15 > 4000   AND a.date >= '1997-01-01';
SELECT COUNT(*) AS classic_card_count FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE c.type = 'classic'   AND d.type = 'OWNER';
SELECT COUNT(*) AS male_client_count FROM client c JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'M'   AND d.A2 = 'Hl.m. Praha';
SELECT      CAST(SUM(CASE WHEN type = 'gold' AND issued < '1998-01-01' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percent FROM card;
SELECT c.client_id FROM loan l JOIN disp d ON l.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE d.type = 'OWNER' ORDER BY l.amount DESC LIMIT 1;
SELECT d.A15 FROM account a JOIN district d ON a.district_id = d.district_id WHERE a.account_id = 532;
SELECT a.district_id FROM account a JOIN order o ON a.account_id = o.account_id WHERE o.order_id = 33333;
SELECT     t.* FROM trans AS t JOIN disp AS d   ON t.account_id = d.account_id WHERE d.client_id = 3356   AND t.operation = 'VYBER';
SELECT COUNT(*) AS count FROM account a JOIN loan l ON a.account_id = l.account_id WHERE a.frequency = 'POPLATEK TYDNE'   AND l.amount < 200000;
SELECT c.type FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE d.client_id = 13539;
SELECT d.A3 FROM client c JOIN district d ON c.district_id = d.district_id WHERE c.client_id = 3541;
SELECT d.A2 FROM district d JOIN account a ON d.district_id = a.district_id JOIN loan l ON a.account_id = l.account_id WHERE l.status = 'A' GROUP BY d.district_id ORDER BY COUNT(*) DESC LIMIT 1;
SELECT     c.client_id FROM     `order` o JOIN     disp d     ON o.account_id = d.account_id JOIN     client c     ON d.client_id = c.client_id WHERE     o.order_id = 32423;
SELECT     t.* FROM trans AS t JOIN account AS a     ON t.account_id = a.account_id WHERE     a.district_id = 5;
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Jesenik';
SELECT DISTINCT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card cr ON d.disp_id = cr.disp_id WHERE cr.type = 'junior'   AND cr.issued >= '1997-01-01';
SELECT   CAST(SUM(CASE WHEN c.gender = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM client c JOIN disp d   ON c.client_id = d.client_id JOIN account a   ON d.account_id = a.account_id JOIN district dist   ON a.district_id = dist.district_id WHERE dist.A11 > 10000;
WITH male_accounts AS (     SELECT DISTINCT d.account_id     FROM disp d     JOIN client c ON d.client_id = c.client_id     WHERE c.gender = 'M' ), loan_sums AS (     SELECT          SUM(CASE WHEN l.date LIKE '1996%' THEN l.amount ELSE 0 END) AS sum_1996,         SUM(CASE WHEN l.date LIKE '1997%' THEN l.amount ELSE 0 END) AS sum_1997     FROM loan l     JOIN male_accounts ma ON l.account_id = ma.account_id ) SELECT      CASE          WHEN sum_1996 = 0 THEN NULL          ELSE ((sum_1997 - sum_1996) * 100.0) / sum_1996      END AS growth_rate FROM loan_sums;
SELECT COUNT(*) AS credit_card_withdrawals_after_1995 FROM trans WHERE operation = 'VYBER KARTOU'   AND date > '1995-12-31';
SELECT     (SELECT SUM(A16)      FROM district      WHERE A3 = 'North Bohemia'        AND A14 = 1996)   -     (SELECT SUM(A16)      FROM district      WHERE A3 = 'East Bohemia'        AND A14 = 1996) AS difference;
SELECT COUNT(*) FROM disp WHERE account_id BETWEEN 1 AND 10   AND type IN ('OWNER', 'DISPONENT');
SELECT     a.frequency,     t.k_symbol FROM account a JOIN trans t   ON a.account_id = t.account_id WHERE a.account_id = 3   AND t.amount = 3539 LIMIT 1;
SELECT   strftime('%Y', c.birth_date) AS birth_year FROM client c JOIN disp d   ON c.client_id = d.client_id WHERE d.client_id = 130   AND d.type = 'OWNER';
SELECT COUNT(*) FROM account a JOIN disp d ON a.account_id = d.account_id WHERE d.type = 'OWNER'   AND a.frequency = 'POPLATEK PO OBRATU';
SELECT     l.amount,     l.status FROM loan AS l JOIN disp AS d   ON l.account_id = d.account_id WHERE d.client_id = 992;
SELECT      t.balance AS sum_after_transaction,     c.gender AS owner_gender FROM trans t JOIN disp d ON t.account_id = d.account_id AND d.type = 'OWNER' JOIN client c ON d.client_id = c.client_id WHERE t.trans_id = 851   AND c.client_id = 4;
SELECT c.type FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE d.client_id = 9;
SELECT     SUM(t.amount) AS total_paid FROM trans t JOIN disp d     ON t.account_id = d.account_id JOIN client c     ON d.client_id = c.client_id WHERE     c.client_id = 617     AND t.type = 'VYDAJ'     AND strftime('%Y', t.date) = '1998';
SELECT DISTINCT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE c.birth_date BETWEEN '1983-01-01' AND '1987-12-31'   AND dist.A3 = 'East Bohemia';
WITH ranked_clients AS (     SELECT         c.client_id,         l.loan_id,         l.amount,         ROW_NUMBER() OVER (             PARTITION BY c.client_id             ORDER BY l.amount DESC         ) AS rn     FROM client c     JOIN disp d ON c.client_id = d.client_id     JOIN loan l ON d.account_id = l.account_id     WHERE c.gender = 'F' ), max_loans AS (     SELECT         client_id,         amount     FROM ranked_clients     WHERE rn = 1 ) SELECT     client_id FROM max_loans ORDER BY amount DESC LIMIT 3;
SELECT COUNT(*) AS count FROM client c JOIN disp d ON c.client_id = d.client_id JOIN trans t ON d.account_id = t.account_id WHERE c.gender = 'M'   AND c.birth_date BETWEEN '1974-01-01' AND '1976-12-31'   AND t.k_symbol = 'SIPO'   AND t.amount > 4000;
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Beroun'   AND a.date > '1996-12-31';
SELECT COUNT(DISTINCT c.client_id) AS female_junior_card_count FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card cd ON d.disp_id = cd.disp_id WHERE c.gender = 'F'   AND cd.type = 'junior';
SELECT     CAST(SUM(CASE WHEN c.gender = 'F' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE dist.A3 LIKE '%Prague%'
SELECT     CAST(SUM(CASE WHEN c.gender = 'M' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE';
SELECT COUNT(*) AS owner_count FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id WHERE d.type = 'OWNER'   AND a.frequency = 'POPLATEK TYDNE';
SELECT     a.account_id FROM account AS a JOIN loan AS l   ON a.account_id = l.account_id WHERE     l.duration > 24     AND a.date < '1997-01-01'     AND l.amount = (         SELECT MIN(l2.amount)         FROM loan AS l2         JOIN account AS a2           ON l2.account_id = a2.account_id         WHERE             l2.duration > 24             AND a2.date < '1997-01-01'     );
SELECT     a.account_id FROM     account a     JOIN disp d ON a.account_id = d.account_id     JOIN client c ON d.client_id = c.client_id     JOIN district dist ON c.district_id = dist.district_id WHERE     c.gender = 'F'     AND c.birth_date = (         SELECT MIN(c2.birth_date)         FROM client c2         WHERE c2.gender = 'F'     )     AND dist.A11 = (         SELECT MIN(dist2.A11)         FROM district dist2     );
SELECT COUNT(*) AS client_count FROM client c JOIN district d ON c.district_id = d.district_id WHERE d.A3 = 'east Bohemia'   AND strftime('%Y', c.birth_date) = '1920';
SELECT COUNT(*) AS loan_count FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.duration = 24   AND a.frequency = 'POPLATEK TYDNE';
SELECT AVG(l.amount) AS average_loan_amount FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.status IN ('C', 'D')   AND a.frequency = 'POPLATEK PO OBRATU';
SELECT DISTINCT c.client_id, c.district_id FROM client c JOIN disp d ON c.client_id = d.client_id WHERE d.type = 'OWNER';
SELECT     c.client_id,     (strftime('%Y', 'now') - strftime('%Y', c.birth_date)) AS age FROM client c JOIN disp d     ON c.client_id = d.client_id JOIN card cd     ON d.disp_id = cd.disp_id WHERE     cd.type = 'gold'     AND d.type = 'OWNER';
SELECT bond_type FROM bond GROUP BY bond_type ORDER BY COUNT(bond_type) DESC LIMIT 1;
SELECT COUNT(DISTINCT m.molecule_id) AS count FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE m.label = '-'   AND a.element = 'cl';
SELECT AVG(CASE WHEN a.element = 'o' THEN 1 ELSE 0 END) AS avg_oxygen_atoms FROM atom a JOIN bond b ON a.molecule_id = b.molecule_id WHERE b.bond_type = '-';
SELECT   CAST(SUM(CASE WHEN b.bond_type = '-' THEN 1 ELSE 0 END) AS REAL) * 1.0 / COUNT(a.atom_id) AS average_single_bonds FROM molecule m JOIN atom a   ON m.molecule_id = a.molecule_id JOIN connected c   ON a.atom_id = c.atom_id JOIN bond b   ON c.bond_id = b.bond_id WHERE m.label = '+';
SELECT COUNT(DISTINCT m.molecule_id) AS non_carcinogenic_count FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE a.element = 'na'   AND m.label = '-';
SELECT DISTINCT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE b.bond_type = '#'   AND m.label = '+';
SELECT      CAST(SUM(CASE WHEN a.element = 'c' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(a.atom_id) AS percentage FROM atom a JOIN bond b ON a.molecule_id = b.molecule_id WHERE b.bond_type = '=';
SELECT COUNT(*) AS count FROM bond WHERE bond_type = '#';
SELECT COUNT(*) AS count FROM atom WHERE element <> 'br';
SELECT COUNT(*) AS carcinogenic_count FROM molecule WHERE molecule_id BETWEEN 'TR000' AND 'TR099'   AND label = '+';
SELECT DISTINCT m.molecule_id FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE a.element = 'c';
SELECT DISTINCT a.element FROM connected c JOIN atom a ON c.atom_id = a.atom_id WHERE c.bond_id = 'TR004_8_9' UNION SELECT DISTINCT a.element FROM connected c JOIN atom a ON c.atom_id2 = a.atom_id WHERE c.bond_id = 'TR004_8_9';
SELECT DISTINCT a.element FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '=';
SELECT     m.label FROM atom AS a JOIN molecule AS m     ON a.molecule_id = m.molecule_id WHERE a.element = 'h' GROUP BY     m.label ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT DISTINCT b.bond_type FROM bond b JOIN connected c ON b.bond_id = c.bond_id JOIN atom a ON c.atom_id = a.atom_id WHERE a.element = 'cl';
SELECT DISTINCT c.atom_id, c.atom_id2 FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '-';
SELECT DISTINCT c.atom_id, c.atom_id2 FROM connected c JOIN molecule m ON c.bond_id = (     SELECT b.bond_id     FROM bond b     WHERE b.molecule_id = m.molecule_id     LIMIT 1 ) WHERE m.label = '-';
SELECT     a.element FROM     atom a JOIN     molecule m     ON a.molecule_id = m.molecule_id WHERE     m.label = '-' GROUP BY     a.element ORDER BY     COUNT(a.element) ASC LIMIT 1;
SELECT b.bond_type FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE (c.atom_id = 'TR004_8' AND c.atom_id2 = 'TR004_20')    OR (c.atom_id = 'TR004_20' AND c.atom_id2 = 'TR004_8');
SELECT DISTINCT m.label FROM molecule m WHERE m.label NOT IN (     SELECT m2.label     FROM molecule m2     JOIN atom a ON m2.molecule_id = a.molecule_id     WHERE a.element = 'sn' );
SELECT     COUNT(DISTINCT a.atom_id) AS atom_count FROM atom a JOIN molecule m     ON a.molecule_id = m.molecule_id JOIN bond b     ON a.molecule_id = b.molecule_id WHERE     a.element IN ('i', 's')     AND b.bond_type = '-';
SELECT     c.atom_id,     c.atom_id2 FROM connected AS c JOIN bond AS b   ON c.bond_id = b.bond_id WHERE b.bond_type = '#';
SELECT DISTINCT a.atom_id FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN atom a2 ON c.atom_id2 = a2.atom_id WHERE a2.molecule_id = 'TR181';
SELECT      CAST(SUM(CASE WHEN a.element = 'f' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(DISTINCT m.molecule_id) AS percentage FROM molecule m LEFT JOIN atom a ON m.molecule_id = a.molecule_id WHERE m.label = '+';
SELECT      CAST(SUM(CASE WHEN b.bond_type = '#' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(b.bond_id) AS percent FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE m.label = '+';
