WITH bond_counts AS (     SELECT          b.bond_type,         COUNT(*) AS cnt     FROM bond b     WHERE b.molecule_id = 'TR010'     GROUP BY b.bond_type ), ranked_bonds AS (     SELECT          bc.bond_type,         bc.cnt,         ROW_NUMBER() OVER (ORDER BY bc.cnt DESC) AS rn     FROM bond_counts bc ) SELECT      rb.bond_type,     CASE          WHEN m.label = '+' THEN 'carcinogenic'         ELSE 'not carcinogenic'     END AS carcinogenic_status FROM ranked_bonds rb JOIN molecule m ON m.molecule_id = 'TR010' WHERE rb.rn = 1;
SELECT DISTINCT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE m.label = '-'   AND b.bond_type = '-' ORDER BY m.molecule_id LIMIT 3;
SELECT bond_id FROM bond WHERE molecule_id = 'TR006' ORDER BY bond_id ASC LIMIT 2;
