SELECT COUNT(DISTINCT b.molecule_id) AS molecule_count FROM bond b WHERE b.bond_type = '#';
SELECT COUNT(DISTINCT c.bond_id) AS connection_count FROM connected c JOIN atom a ON c.atom_id = a.atom_id WHERE a.atom_id LIKE 'TR%_19';
