SELECT DISTINCT b.bond_id FROM bond b JOIN connected c1 ON b.bond_id = c1.bond_id JOIN atom a1 ON c1.atom_id = a1.atom_id JOIN connected c2 ON b.bond_id = c2.bond_id JOIN atom a2 ON c2.atom_id2 = a2.atom_id WHERE a1.element = 'p'   AND a2.element = 'n';
WITH double_bond_counts AS (     SELECT          b.molecule_id,         COUNT(*) AS double_bond_count     FROM bond b     WHERE b.bond_type = '='     GROUP BY b.molecule_id ), ranked_molecules AS (     SELECT          d.molecule_id,         d.double_bond_count,         ROW_NUMBER() OVER (ORDER BY d.double_bond_count DESC) AS rn     FROM double_bond_counts d ) SELECT      CASE          WHEN m.label = '+' THEN 'Yes'         ELSE 'No'     END AS is_carcinogenic FROM ranked_molecules r JOIN molecule m ON r.molecule_id = m.molecule_id WHERE r.rn = 1;
SELECT   CAST(COUNT(DISTINCT T1.bond_id) AS REAL) / COUNT(DISTINCT T2.atom_id) AS average_bonds FROM bond AS T1 JOIN connected AS T2   ON T1.bond_id = T2.bond_id JOIN atom AS T3   ON T2.atom_id = T3.atom_id WHERE T3.element = 'i';
SELECT     b.bond_type,     b.bond_id FROM bond AS b JOIN connected AS c   ON b.bond_id = c.bond_id JOIN atom AS a   ON c.atom_id = a.atom_id WHERE     CAST(SUBSTR(a.atom_id, 7, 2) AS INTEGER) = 45;
