SELECT DISTINCT a.element FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '#';
WITH bond_elements AS (     SELECT         b.bond_id,         a1.element AS elem1,         a2.element AS elem2     FROM bond b     JOIN connected c ON b.bond_id = c.bond_id     JOIN atom a1 ON c.atom_id = a1.atom_id     JOIN atom a2 ON c.atom_id2 = a2.atom_id     WHERE a1.atom_id < a2.atom_id ), element_counts AS (     SELECT         elem1,         elem2,         COUNT(*) AS cnt     FROM bond_elements     GROUP BY elem1, elem2 ), max_count AS (     SELECT MAX(cnt) AS max_cnt     FROM element_counts ), total_bonds AS (     SELECT COUNT(*) AS total     FROM bond ) SELECT     CAST(         SUM(CASE WHEN ec.cnt = mc.max_cnt THEN ec.cnt ELSE 0 END) AS REAL     ) * 100.0 / tb.total AS percentage FROM element_counts ec CROSS JOIN max_count mc CROSS JOIN total_bonds tb;
SELECT      CAST(SUM(CASE WHEN m.label = '+' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(b.bond_id) AS proportion FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE b.bond_type = '-';
