SELECT COUNT(*) AS card_count FROM cards c JOIN rulings r ON c.uuid = r.uuid WHERE c.rarity = 'rare'   AND r.date = '2007-02-01';
SELECT st.translation FROM sets s JOIN set_translations st ON s.code = st.setCode WHERE s.baseSetSize = 180   AND s.block = 'Ravnica';
SELECT      CAST(SUM(CASE WHEN c.hasContentWarning = 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(c.id) AS percentage FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE l.format = 'commander'   AND l.status = 'Legal';
SELECT     CAST(         SUM(CASE WHEN fd.language = 'French' THEN 1 ELSE 0 END) AS REAL     ) * 100 / COUNT(*) AS percentage FROM cards c LEFT JOIN foreign_data fd     ON c.uuid = fd.uuid WHERE     c.power IS NULL     OR c.power = '*';
SELECT      CAST(SUM(CASE WHEN s.type = 'expansion' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM      set_translations st JOIN      sets s ON st.setCode = s.code WHERE      st.language = 'Japanese';
