SELECT COUNT(*) AS count FROM cards WHERE borderColor = 'borderless'   AND edhrecRank > 12000;
SELECT COUNT(*) AS count FROM cards WHERE isOversized = 1   AND isReprint = 1   AND isPromo = 1;
SELECT     c.name FROM     cards c WHERE     (c.power IS NULL OR c.power = '*')     AND c.promoTypes = 'arenaleague' ORDER BY     c.name ASC LIMIT 3;
SELECT fd.language FROM foreign_data AS fd WHERE fd.multiverseid = 149934;
SELECT c1.id FROM cards c1 JOIN cards c2 ON c1.cardKingdomFoilId = c2.cardKingdomFoilId WHERE c1.cardKingdomFoilId IS NOT NULL   AND c1.cardKingdomId IS NOT NULL   AND c2.cardKingdomFoilId IS NOT NULL   AND c2.cardKingdomId IS NOT NULL ORDER BY c1.cardKingdomFoilId ASC LIMIT 3;
SELECT      (COUNT(CASE WHEN c.isTextless = 1 AND c.layout = 'normal' THEN 1 END) * 100.0) /      NULLIF(COUNT(CASE WHEN c.isTextless = 1 THEN 1 END), 0) AS proportion FROM cards c;
SELECT c.number FROM cards c WHERE c.side IS NULL   AND c.subtypes LIKE '%Angel%'   AND c.subtypes LIKE '%Wizard%';
SELECT name FROM sets WHERE mtgoCode IS NULL OR mtgoCode = '' ORDER BY name ASC LIMIT 3;
SELECT     st.language FROM set_translations AS st JOIN sets AS s     ON st.setCode = s.code WHERE     s.mcmName = 'Archenemy'     AND st.setCode = 'ARC';
SELECT s.name, st.translation FROM sets s JOIN set_translations st ON s.code = st.setCode WHERE s.id = 5;
SELECT     st.language,     s.type FROM sets AS s JOIN set_translations AS st     ON s.code = st.setCode WHERE s.id = 206;
SELECT     s.id,     s.name FROM sets s JOIN cards c   ON c.setCode = s.code JOIN foreign_data fd   ON fd.uuid = c.uuid WHERE s.block = 'Shadowmoor'   AND fd.language = 'Italian' GROUP BY s.id, s.name ORDER BY s.name ASC LIMIT 2;
SELECT s.id FROM sets s JOIN set_translations st ON s.code = st.setCode WHERE s.isForeignOnly = 1   AND s.isFoilOnly = 1   AND st.language = 'Japanese';
