SELECT      CASE          WHEN s.isForeignOnly = 1 THEN 'Yes'          ELSE 'No'      END AS is_only_available_outside_us FROM cards c JOIN sets s ON c.setCode = s.code WHERE c.name = 'Adarkar Valkyrie' LIMIT 1;
