SELECT COUNT(*) AS count FROM cards c JOIN sets s ON c.setCode = s.code WHERE s.name = 'Coldsnap'   AND c.convertedManaCost > 5   AND (c.power = '*' OR c.power IS NULL);
SELECT     fd.flavorText FROM foreign_data AS fd JOIN cards AS c     ON fd.uuid = c.uuid WHERE     c.name = 'Ancestor''s Chosen'     AND fd.language = 'Italian';
SELECT DISTINCT fd.language FROM foreign_data fd JOIN cards c ON fd.uuid = c.uuid WHERE c.name = 'Ancestor''s Chosen'   AND fd.flavorText IS NOT NULL;
SELECT fd.type FROM foreign_data fd JOIN cards c ON fd.uuid = c.uuid WHERE c.name = 'Ancestor''s Chosen'   AND fd.language = 'German';
SELECT DISTINCT r.text FROM rulings r JOIN cards c ON r.uuid = c.uuid JOIN sets s ON c.setCode = s.code WHERE s.name = 'Coldsnap'   AND r.text IS NOT NULL;
WITH coldsnap_cards AS (     SELECT         c.uuid,         c.convertedManaCost     FROM cards c     JOIN sets s ON c.setCode = s.code     WHERE s.name = 'Coldsnap' ), max_cmc AS (     SELECT MAX(convertedManaCost) AS max_cmc     FROM coldsnap_cards ), top_cards AS (     SELECT cc.uuid     FROM coldsnap_cards cc     JOIN max_cmc mc ON cc.convertedManaCost = mc.max_cmc ) SELECT fd.name FROM foreign_data fd JOIN top_cards tc ON fd.uuid = tc.uuid WHERE fd.language = 'Italian';
SELECT r.date FROM rulings r JOIN cards c ON r.uuid = c.uuid WHERE c.name = 'Reminisce';
SELECT      CAST(SUM(CASE WHEN c.convertedManaCost = 7 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM cards c JOIN sets s ON c.setCode = s.code WHERE s.name = 'Coldsnap';
SELECT      CAST(SUM(CASE WHEN c.cardKingdomFoilId IS NOT NULL AND c.cardKingdomId IS NOT NULL THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM cards c JOIN sets s ON c.setCode = s.code WHERE s.name = 'Coldsnap';
SELECT code FROM sets WHERE releaseDate = '2017-07-14';
SELECT keyruneCode FROM sets WHERE code = 'PKHC';
SELECT mcmId FROM sets WHERE code = 'SS2';
SELECT mcmName FROM sets WHERE releaseDate = '2017-06-09';
SELECT     s.type FROM sets AS s WHERE s.name LIKE '%From the Vault: Lore%';
SELECT parentCode FROM sets WHERE name = 'Commander 2014 Oversized';
SELECT     c.name,     r.text AS ruling_text,     CASE         WHEN c.hasContentWarning = 1 THEN 'Yes'         ELSE 'No'     END AS has_missing_or_degraded_properties FROM cards c LEFT JOIN rulings r     ON c.uuid = r.uuid WHERE c.artist = 'Jim Pavelec';
SELECT s.releaseDate FROM cards c JOIN sets s ON c.setCode = s.code WHERE c.name = 'Evacuation';
