SELECT COUNT(st.translation) AS translation_count FROM set_translations st JOIN sets s ON st.setCode = s.code WHERE s.name = 'Tenth Edition'   AND st.translation IS NOT NULL;
SELECT     st.translation FROM cards AS c JOIN sets AS s     ON c.setCode = s.code JOIN set_translations AS st     ON s.code = st.setCode WHERE     c.name = 'Fellwar Stone'     AND st.language = 'Japanese';
SELECT     c.name FROM cards AS c JOIN sets AS s     ON c.setCode = s.code WHERE     s.name = 'Journey into Nyx Hero''s Path' ORDER BY     c.convertedManaCost DESC LIMIT 1;
SELECT s.releaseDate FROM sets s JOIN set_translations st ON s.code = st.setCode WHERE st.translation = 'Ola de frío';
