SELECT COUNT(*) AS card_count FROM cards c JOIN sets s ON c.setCode = s.code WHERE s.name = 'World Championship Decks 2004'   AND c.convertedManaCost = 3;
SELECT     st.translation FROM sets AS s JOIN set_translations AS st     ON s.code = st.setCode WHERE s.name = 'Mirrodin'   AND st.language = 'Chinese Simplified';
SELECT      CAST(SUM(CASE WHEN s.isNonFoilOnly = 1 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM sets s JOIN set_translations st ON s.code = st.setCode WHERE st.language = 'Japanese';
SELECT     CAST(SUM(CASE WHEN c.isOnlineOnly = 1 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM cards c JOIN sets s ON c.setCode = s.code JOIN set_translations st ON s.code = st.setCode WHERE st.language = 'Portuguese (Brazil)';
SELECT DISTINCT c.availability FROM cards c WHERE c.artist = 'Aleksi Briclot'   AND c.isTextless = 1;
SELECT id FROM sets ORDER BY baseSetSize DESC LIMIT 1;
SELECT c.artist FROM cards c WHERE c.side IS NULL ORDER BY c.convertedManaCost DESC LIMIT 1;
SELECT MAX(frameEffects) AS most_common_frame_effects FROM cards WHERE cardKingdomFoilId IS NOT NULL   AND cardKingdomId IS NOT NULL;
SELECT COUNT(*) AS card_count FROM cards WHERE (power IS NULL OR power = '*')   AND hasFoil = 0   AND duelDeck = 'a';
SELECT id FROM sets WHERE type = 'commander' ORDER BY totalSetSize DESC LIMIT 1;
SELECT     c.name FROM     cards c JOIN     legalities l     ON c.uuid = l.uuid WHERE     l.format = 'duel' ORDER BY     c.convertedManaCost DESC LIMIT 10;
SELECT     c.originalReleaseDate,     l.format FROM cards AS c JOIN legalities AS l   ON c.uuid = l.uuid WHERE c.rarity = 'mythic'   AND l.status = 'legal'   AND c.originalReleaseDate = (       SELECT MIN(originalReleaseDate)       FROM cards       WHERE rarity = 'mythic'   );
SELECT COUNT(DISTINCT c.id) AS card_count FROM cards c JOIN foreign_data fd ON c.uuid = fd.uuid WHERE c.artist = 'Volkan Baǵa'   AND fd.language = 'French';
SELECT COUNT(*) AS count FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE c.rarity = 'rare'   AND c.types = 'Enchantment'   AND c.name = 'Abundance'   AND l.status = 'Legal';
WITH banned_counts AS (     SELECT         l.format,         COUNT(*) AS banned_count     FROM legalities l     WHERE l.status = 'Banned'     GROUP BY l.format ), max_banned AS (     SELECT MAX(banned_count) AS max_count     FROM banned_counts ) SELECT     l.format,     c.name FROM legalities l JOIN cards c ON l.uuid = c.uuid JOIN banned_counts bc ON l.format = bc.format JOIN max_banned mb ON bc.banned_count = mb.max_count WHERE l.status = 'Banned' ORDER BY l.format, c.name;
SELECT     st.language FROM sets AS s JOIN set_translations AS st     ON s.code = st.setCode WHERE s.name = 'Battlebond';
SELECT     l.format FROM cards AS c JOIN legalities AS l     ON c.uuid = l.uuid WHERE c.artist = (     SELECT artist     FROM cards     WHERE artist IS NOT NULL     GROUP BY artist     ORDER BY COUNT(*) ASC, artist ASC     LIMIT 1 );
SELECT     l.status FROM cards AS c JOIN legalities AS l     ON c.uuid = l.uuid WHERE     c.frameVersion = '1997'     AND c.artist = 'D. Alexander Gregory'     AND c.hasContentWarning = 1     AND l.format = 'legacy';
SELECT     c.name,     l.format FROM cards AS c JOIN legalities AS l     ON c.uuid = l.uuid WHERE     c.edhrecRank = 1     AND l.status = 'Banned';
SELECT     AVG(CAST(id AS REAL)) AS annual_average_sets FROM sets WHERE releaseDate BETWEEN '2012-01-01' AND '2015-12-31';
SELECT DISTINCT artist FROM cards WHERE borderColor = 'black'   AND availability = 'arena';
SELECT DISTINCT c.uuid FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE l.format = 'oldschool'   AND l.status IN ('banned', 'restricted');
SELECT COUNT(*) AS count FROM cards WHERE artist = 'Matthew D. Wilson'   AND availability = 'paper';
SELECT     r.text FROM rulings AS r JOIN cards AS c     ON r.uuid = c.uuid WHERE c.artist = 'Kev Walker' ORDER BY r.date DESC;
SELECT     c.name,     l.format FROM cards AS c JOIN sets AS s     ON c.setCode = s.code JOIN legalities AS l     ON c.uuid = l.uuid WHERE     s.name = 'Hour of Devastation'     AND l.status = 'Legal';
SELECT s.name FROM sets s WHERE EXISTS (     SELECT 1     FROM set_translations st     WHERE st.setCode = s.code       AND st.language = 'Korean' ) AND NOT EXISTS (     SELECT 1     FROM set_translations st     WHERE st.setCode = s.code       AND st.language LIKE '%Japanese%' );
SELECT DISTINCT c.frameVersion, c.name FROM cards c WHERE c.artist = 'Allen Williams' UNION SELECT DISTINCT c.frameVersion, c.name FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE l.status = 'Banned';
SELECT DisplayName, MAX(Reputation) AS MaxReputation FROM users WHERE DisplayName IN ('Harlan', 'Jarrod Dixon') GROUP BY DisplayName ORDER BY MaxReputation DESC LIMIT 1;
SELECT DisplayName FROM users WHERE strftime('%Y', CreationDate) = '2011';
SELECT COUNT(*) AS user_count FROM users WHERE LastAccessDate > '2014-09-01';
SELECT DisplayName FROM users ORDER BY Views DESC LIMIT 1;
SELECT COUNT(*) AS count FROM users WHERE UpVotes > 100   AND DownVotes > 1;
SELECT COUNT(*) AS user_count FROM users WHERE Views > 10   AND strftime('%Y', CreationDate) > '2013';
SELECT COUNT(*) AS post_count FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE u.DisplayName = 'csgillespie';
SELECT p.Title FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE u.DisplayName = 'csgillespie';
SELECT u.DisplayName FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE p.Title = 'Eliciting priors from experts';
SELECT     p.Title FROM posts AS p JOIN users AS u     ON p.OwnerUserId = u.Id WHERE     u.DisplayName = 'csgillespie' ORDER BY     p.ViewCount DESC LIMIT 1;
SELECT u.DisplayName FROM posts p JOIN users u ON p.OwnerUserId = u.Id ORDER BY p.FavoriteCount DESC LIMIT 1;
SELECT     SUM(p.CommentCount) AS total_comments FROM posts p JOIN users u     ON p.OwnerUserId = u.Id WHERE     u.DisplayName = 'csgillespie';
SELECT MAX(p.AnswerCount) FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE u.DisplayName = 'csgillespie';
SELECT     u.DisplayName FROM posts AS p JOIN users AS u     ON p.LastEditorUserId = u.Id WHERE p.Title = 'Examples for teaching: Correlation does not mean causation';
SELECT COUNT(*) AS root_post_count FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE u.DisplayName = 'csgillespie'   AND p.ParentId IS NULL;
SELECT DISTINCT u.DisplayName FROM users u JOIN posts p ON u.Id = p.OwnerUserId WHERE p.ClosedDate IS NOT NULL;
SELECT     COUNT(*) FROM posts p JOIN users u   ON p.OwnerUserId = u.Id WHERE u.Age > 65   AND p.Score >= 20;
SELECT u.Location FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE p.Title = 'Eliciting priors from experts';
SELECT p.Body FROM tags t JOIN posts p ON t.ExcerptPostId = p.Id WHERE t.TagName = 'bayesian';
SELECT p.Body FROM tags t JOIN posts p ON t.ExcerptPostId = p.Id ORDER BY t.Count DESC LIMIT 1;
SELECT COUNT(*) AS badge_count FROM badges b JOIN users u ON b.UserId = u.Id WHERE u.DisplayName = 'csgillespie';
SELECT b.Name FROM badges b JOIN users u ON b.UserId = u.Id WHERE u.DisplayName = 'csgillespie';
