SELECT     (         SUM(CASE WHEN a.alignment = 'Bad' THEN 1 ELSE 0 END) * 100.0         / COUNT(s.id)     ) AS percentage_bad_alignment,     SUM(CASE WHEN a.alignment = 'Bad' AND p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS count_bad_marvel FROM superhero s LEFT JOIN alignment a ON s.alignment_id = a.id LEFT JOIN publisher p ON s.publisher_id = p.id;
