SELECT MAX(r.year) AS last_season FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Brands Hatch'   AND r.name = 'British Grand Prix';
SELECT COUNT(DISTINCT r.year) AS seasons_count FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone Circuit'   AND r.name = 'British Grand Prix';
SELECT     d.forename,     d.surname FROM     driverStandings AS ds JOIN     drivers AS d     ON ds.driverId = d.driverId JOIN     races AS r     ON ds.raceId = r.raceId WHERE     r.year = 2010     AND r.name = 'Singapore Grand Prix' ORDER BY     ds.position;
SELECT     d.forename,     d.surname,     ds.points FROM driverStandings AS ds JOIN drivers AS d     ON ds.driverId = d.driverId ORDER BY     ds.points DESC LIMIT 1;
SELECT     d.forename,     d.surname,     r.points FROM results r JOIN drivers d     ON r.driverId = d.driverId JOIN races ra     ON r.raceId = ra.raceId WHERE ra.year = 2017   AND ra.name = 'Chinese Grand Prix' ORDER BY r.points DESC LIMIT 3;
SELECT     d.forename,     d.surname,     r.name FROM lapTimes AS lt JOIN drivers AS d     ON lt.driverId = d.driverId JOIN races AS r     ON lt.raceId = r.raceId ORDER BY lt.milliseconds ASC LIMIT 1;
SELECT AVG(lt.milliseconds) AS average_lap_time FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId JOIN races r ON lt.raceId = r.raceId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton'   AND r.name = 'Malaysian Grand Prix'   AND r.year = 2009;
SELECT     CAST(         SUM(CASE WHEN r.position > 1 THEN 1 ELSE 0 END) AS REAL     ) * 100.0 / COUNT(r.raceId) AS percentage FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.surname = 'Hamilton'   AND ra.year >= 2010;
WITH driver_wins AS (     SELECT         d.driverId,         d.forename,         d.surname,         d.nationality,         SUM(ds.wins) AS total_wins     FROM drivers d     JOIN driverStandings ds ON d.driverId = ds.driverId     GROUP BY d.driverId, d.forename, d.surname, d.nationality ), max_wins AS (     SELECT MAX(total_wins) AS max_total_wins     FROM driver_wins ), driver_max_points AS (     SELECT         d.driverId,         MAX(ds.points) AS max_points     FROM drivers d     JOIN driverStandings ds ON d.driverId = ds.driverId     GROUP BY d.driverId ) SELECT     dw.forename,     dw.surname,     dw.nationality,     dmp.max_points FROM driver_wins dw JOIN max_wins mw ON dw.total_wins = mw.max_total_wins JOIN driver_max_points dmp ON dw.driverId = dmp.driverId;
SELECT      (strftime('%Y', 'now') - strftime('%Y', d.dob)) AS age,     d.forename || ' ' || d.surname AS name FROM      drivers d WHERE      d.nationality = 'Japanese' ORDER BY      d.dob DESC LIMIT 1;
SELECT c.circuitId FROM circuits c JOIN races r ON c.circuitId = r.circuitId WHERE r.year BETWEEN 1990 AND 2000 GROUP BY c.circuitId HAVING COUNT(r.raceId) = 4;
SELECT     c.name AS circuit_name,     c.location AS circuit_location,     r.name AS race_name FROM circuits c JOIN races r     ON c.circuitId = r.circuitId WHERE     c.country = 'USA'     AND r.year = 2006;
SELECT     r.name,     c.name,     c.location FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE     strftime('%m', r.date) = '09'     AND strftime('%Y', r.date) = '2005';
SELECT r.name FROM results res JOIN drivers d ON res.driverId = d.driverId JOIN races r ON res.raceId = r.raceId WHERE d.forename = 'Alex'   AND d.surname = 'Yoong'   AND res.position < 20;
SELECT COUNT(*) AS win_count FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId JOIN circuits c ON ra.circuitId = c.circuitId WHERE d.forename = 'Michael'   AND d.surname = 'Schumacher'   AND c.name = 'Sepang International Circuit'   AND r.points = (       SELECT MAX(r2.points)       FROM results r2       WHERE r2.raceId = r.raceId   );
SELECT     r.name AS race,     r.year AS year FROM results AS res JOIN drivers AS d     ON res.driverId = d.driverId JOIN races AS r     ON res.raceId = r.raceId WHERE     d.forename = 'Michael'     AND d.surname = 'Schumacher'     AND res.fastestLap IS NOT NULL     AND res.milliseconds = (         SELECT MIN(res2.milliseconds)         FROM results AS res2         JOIN drivers AS d2             ON res2.driverId = d2.driverId         WHERE             d2.forename = 'Michael'             AND d2.surname = 'Schumacher'             AND res2.fastestLap IS NOT NULL     );
SELECT AVG(r.points) AS average_points FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.forename = 'Eddie'   AND d.surname = 'Irvine'   AND ra.year = 2000;
SELECT     r.year,     res.points FROM results AS res JOIN drivers AS d     ON res.driverId = d.driverId JOIN races AS r     ON res.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton' ORDER BY     r.year ASC LIMIT 1;
SELECT     r.raceId,     r.name,     c.country FROM     races r JOIN     circuits c     ON r.circuitId = c.circuitId WHERE     r.year = 2017 ORDER BY     r.date;
SELECT     r.name AS race_name,     r.year AS year,     c.location AS circuit_location FROM results AS res JOIN races AS r     ON res.raceId = r.raceId JOIN circuits AS c     ON r.circuitId = c.circuitId ORDER BY res.laps DESC LIMIT 1;
SELECT     CAST(SUM(CASE WHEN c.country = 'Germany' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM races r JOIN circuits c   ON r.circuitId = c.circuitId WHERE r.name = 'European Grand Prix';
SELECT lat, lng FROM circuits WHERE name = 'Silverstone Circuit';
SELECT name FROM circuits WHERE name IN ('Silverstone Circuit', 'Hockenheimring', 'Hungaroring') ORDER BY lat DESC LIMIT 1;
SELECT circuitRef FROM circuits WHERE name = 'Marina Bay Street Circuit';
SELECT country FROM circuits ORDER BY alt DESC LIMIT 1;
SELECT COUNT(*) AS count FROM drivers WHERE code IS NULL;
SELECT d.nationality FROM drivers d ORDER BY d.dob ASC LIMIT 1;
SELECT surname FROM drivers WHERE nationality = 'Italian';
SELECT url FROM drivers WHERE forename = 'Anthony' AND surname = 'Davidson';
SELECT driverRef FROM drivers WHERE forename = 'Lewis' AND surname = 'Hamilton';
SELECT c.name FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.year = 2009   AND r.name = 'Spanish Grand Prix';
SELECT DISTINCT r.year FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone Circuit';
SELECT r.url FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone Circuit';
SELECT     r.time FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE     r.year = 2010     AND c.name = 'Abu Dhabi Circuit';
SELECT COUNT(*) AS race_count FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy';
SELECT     r.date FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.name = 'Circuit de Barcelona-Catalunya';
SELECT DISTINCT c.url FROM circuits c JOIN races r   ON c.circuitId = r.circuitId WHERE r.name = 'Spanish Grand Prix'   AND r.year = 2009;
SELECT MIN(r.fastestLapTime) AS fastest_lap_time FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     d.forename,     d.surname FROM results r JOIN drivers d     ON r.driverId = d.driverId ORDER BY     CAST(r.fastestLapSpeed AS REAL) DESC LIMIT 1;
SELECT     d.driverRef FROM results r JOIN races ra     ON r.raceId = ra.raceId JOIN drivers d     ON r.driverId = d.driverId WHERE     ra.name = 'Canadian Grand Prix'     AND ra.year = 2007     AND r.position = 1 LIMIT 1;
SELECT DISTINCT r.name FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     r.name FROM results AS res JOIN drivers AS d     ON res.driverId = d.driverId JOIN races AS r     ON res.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND res.rank IS NOT NULL ORDER BY     res.rank ASC LIMIT 1;
SELECT     MAX(r.fastestLapSpeed) FROM results AS r JOIN races AS ra     ON r.raceId = ra.raceId WHERE     ra.name = 'Spanish Grand Prix'     AND ra.year = 2009;
SELECT DISTINCT r.year FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     r.positionOrder FROM results AS r JOIN drivers AS d     ON r.driverId = d.driverId JOIN races AS ra     ON r.raceId = ra.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND ra.name = 'Chinese Grand Prix'     AND ra.year = 2008;
SELECT     d.forename,     d.surname FROM results r JOIN races ra     ON r.raceId = ra.raceId JOIN drivers d     ON r.driverId = d.driverId JOIN circuits c     ON ra.circuitId = c.circuitId WHERE     ra.year = 1989     AND ra.name = 'Australian Grand Prix'     AND r.grid = 4;
SELECT COUNT(DISTINCT r.driverId) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix'   AND r.time IS NOT NULL;
SELECT MIN(r.fastestLapTime) AS fastest_lap FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton'   AND ra.year = 2008   AND ra.name = 'Australian Grand Prix';
SELECT     r.time FROM results AS r JOIN races AS ra     ON r.raceId = ra.raceId WHERE     ra.year = 2008     AND ra.name = 'Chinese Grand Prix'     AND r.position = 2;
SELECT      d.url,     r.time FROM      results r JOIN      drivers d ON r.driverId = d.driverId JOIN      races ra ON r.raceId = ra.raceId WHERE      ra.year = 2008     AND ra.name = 'Australian Grand Prix'     AND r.position = 1     AND r.statusId = 1;
SELECT     COUNT(DISTINCT r.driverId) AS driver_count FROM results r JOIN races ra     ON r.raceId = ra.raceId JOIN drivers d     ON r.driverId = d.driverId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix'   AND d.nationality = 'British';
SELECT COUNT(DISTINCT r.driverId) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008   AND ra.name = 'Chinese Grand Prix'   AND r.time IS NOT NULL   AND r.time <> ''   AND EXISTS (       SELECT 1       FROM results r2       WHERE r2.driverId = r.driverId   );
SELECT     SUM(r.points) AS total_points FROM results r JOIN drivers d     ON r.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT AVG(     CAST(SUBSTR(r.fastestLapTime, 1, INSTR(r.fastestLapTime, ':') - 1) AS REAL) * 60 +     CAST(SUBSTR(r.fastestLapTime, INSTR(r.fastestLapTime, ':') + 1) AS REAL) ) AS average_fastest_lap_time_seconds FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton'   AND r.fastestLapTime IS NOT NULL;
SELECT   CAST(COUNT(CASE WHEN r.time IS NOT NULL THEN 1 END) AS REAL) * 1.0 / COUNT(r.raceId) AS rate FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix';
WITH race_info AS (     SELECT          r.raceId,         r.year,         r.name     FROM races r     WHERE r.year = 2008       AND r.name = 'Australian Grand Prix' ), results_data AS (     SELECT          res.driverId,         res.position,         res.time,         res.milliseconds     FROM results res     INNER JOIN race_info ri ON res.raceId = ri.raceId     WHERE res.time IS NOT NULL ), champion AS (     SELECT          milliseconds AS champion_ms,         time AS champion_time     FROM results_data     WHERE position = 1 ), last_driver AS (     SELECT          milliseconds AS last_ms,         time AS last_time     FROM results_data     WHERE position = (         SELECT MAX(position)          FROM results_data     ) ) SELECT      ROUND(         (             (                 (                     SELECT last_ms                      FROM last_driver                 ) - (                     SELECT champion_ms                      FROM champion                 )             ) * 100.0 / (                 SELECT last_ms                  FROM last_driver             )         ),          2     ) AS percentage_faster FROM champion CROSS JOIN last_driver;
SELECT COUNT(*) AS circuit_count FROM circuits WHERE country = 'Australia'   AND location = 'Adelaide';
SELECT     lat,     lng FROM     circuits WHERE     country = 'USA';
SELECT COUNT(*) AS count FROM drivers WHERE nationality = 'British'   AND dob > '1980-01-01';
SELECT MAX(cr.points) AS max_points FROM constructorResults cr JOIN constructors c   ON cr.constructorId = c.constructorId WHERE c.nationality = 'British';
SELECT c.name FROM constructorStandings cs JOIN constructors c ON cs.constructorId = c.constructorId ORDER BY cs.points DESC LIMIT 1;
SELECT     c.name FROM constructorResults AS cr JOIN constructors AS c     ON cr.constructorId = c.constructorId WHERE     cr.raceId = 291     AND cr.points = 0;
SELECT COUNT(*) FROM (     SELECT         cr.constructorId     FROM constructorResults AS cr     JOIN constructors AS c         ON cr.constructorId = c.constructorId     WHERE c.nationality = 'Japanese'       AND cr.points = 0     GROUP BY cr.constructorId     HAVING COUNT(cr.raceId) = 2 ) AS sub;
SELECT DISTINCT c.name FROM constructorStandings cs JOIN constructors c ON cs.constructorId = c.constructorId WHERE cs.position = 1;
SELECT COUNT(*) FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId JOIN results r ON lt.raceId = r.raceId AND lt.driverId = r.driverId JOIN constructors c ON r.constructorId = c.constructorId WHERE c.nationality = 'French'   AND lt.lap > 50;
SELECT   CAST(     SUM(CASE WHEN r.time IS NOT NULL THEN 1 ELSE 0 END) AS REAL   ) * 100 / COUNT(r.driverId) AS completion_percentage FROM results r JOIN drivers d   ON r.driverId = d.driverId JOIN races ra   ON r.raceId = ra.raceId WHERE d.nationality = 'Japanese'   AND ra.year BETWEEN 2007 AND 2009;
WITH champion_results AS (     SELECT         r.year,         CAST(SUBSTR(res.time, 1, 2) AS INTEGER) * 3600 +         CAST(SUBSTR(res.time, 4, 2) AS INTEGER) * 60 +         CAST(SUBSTR(res.time, 7, 2) AS INTEGER) +         CAST(SUBSTR(res.time, 10, 3) AS REAL) / 1000.0 AS time_seconds     FROM results res     JOIN races r ON res.raceId = r.raceId     WHERE res.position = 1       AND res.time IS NOT NULL       AND r.year < 1975 ) SELECT     year,     AVG(time_seconds) AS avg_time_seconds FROM champion_results GROUP BY year;
SELECT DISTINCT     d.forename,     d.surname FROM drivers d JOIN driverStandings ds     ON d.driverId = ds.driverId WHERE strftime('%Y', d.dob) > '1975'   AND ds.position = 2;
SELECT COUNT(*) AS count FROM drivers d JOIN results r   ON d.driverId = r.driverId WHERE d.nationality = 'Italian'   AND r.time IS NULL;
SELECT     d.forename,     d.surname FROM results r JOIN drivers d     ON r.driverId = d.driverId WHERE r.fastestLapTime IS NOT NULL ORDER BY r.fastestLapTime ASC LIMIT 1;
WITH champion AS (     SELECT         r.driverId     FROM results r     JOIN races ra ON r.raceId = ra.raceId     WHERE ra.year = 2009     ORDER BY r.points DESC, r.position ASC     LIMIT 1 ) SELECT     lt.lap FROM lapTimes lt JOIN champion c ON lt.driverId = c.driverId ORDER BY lt.milliseconds ASC LIMIT 1;
SELECT AVG(r.fastestLapSpeed) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Spanish Grand Prix'   AND ra.year = 2009;
SELECT     r.name,     r.year FROM results AS res JOIN races AS r     ON res.raceId = r.raceId WHERE res.milliseconds IS NOT NULL ORDER BY res.milliseconds ASC LIMIT 1;
SELECT     CAST(         SUM(CASE WHEN CAST(strftime('%Y', d.dob) AS INTEGER) < 1985 AND r.laps > 50 THEN 1 ELSE 0 END) AS REAL     ) * 100.0 / COUNT(r.driverId) AS percentage FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN drivers d ON r.driverId = d.driverId WHERE ra.year BETWEEN 2000 AND 2005;
SELECT COUNT(*) FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId WHERE d.nationality = 'French'   AND lt.milliseconds < 120000;
SELECT code FROM drivers WHERE nationality = 'America';
SELECT raceId FROM races WHERE year = 2009;
SELECT COUNT(DISTINCT driverId) AS driver_count FROM results WHERE raceId = 18;
WITH YoungestDrivers AS (     SELECT          driverId,         code,         nationality,         MAX(CAST(strftime('%Y', dob) AS INTEGER)) AS max_dob_year     FROM drivers     WHERE dob IS NOT NULL     GROUP BY driverId ), RankedDrivers AS (     SELECT          driverId,         code,         nationality,         max_dob_year,         ROW_NUMBER() OVER (ORDER BY max_dob_year DESC) AS rn     FROM YoungestDrivers ) SELECT      code,     CASE WHEN nationality = 'Dutch' THEN 1 ELSE 0 END AS is_netherlandic FROM RankedDrivers WHERE rn <= 3 ORDER BY rn;
SELECT driverRef FROM drivers WHERE forename = 'Robert' AND surname = 'Kubica';
SELECT COUNT(*) AS count FROM drivers WHERE nationality = 'British'   AND strftime('%Y', dob) = '1980';
WITH german_drivers AS (     SELECT          d.driverId,         d.forename,         d.surname,         d.dob     FROM drivers d     WHERE d.nationality = 'German'       AND strftime('%Y', d.dob) BETWEEN '1980' AND '1990' ), earliest_laps AS (     SELECT          lt.driverId,         MIN(lt.time) AS earliest_time     FROM lapTimes lt     INNER JOIN german_drivers gd ON lt.driverId = gd.driverId     GROUP BY lt.driverId ) SELECT      gd.forename,     gd.surname,     el.earliest_time FROM german_drivers gd INNER JOIN earliest_laps el ON gd.driverId = el.driverId ORDER BY el.earliest_time ASC LIMIT 3;
SELECT driverRef FROM drivers WHERE nationality = 'German' ORDER BY dob ASC LIMIT 1;
SELECT DISTINCT d.driverId, d.code FROM drivers d JOIN results r ON d.driverId = r.driverId WHERE strftime('%Y', d.dob) = '1971'   AND r.fastestLapTime IS NOT NULL;
WITH ranked_drivers AS (     SELECT         d.driverId,         d.forename,         d.surname,         d.dob,         lt.time AS lap_time,         ROW_NUMBER() OVER (             PARTITION BY d.driverId             ORDER BY lt.time DESC         ) AS rn     FROM drivers d     JOIN lapTimes lt ON d.driverId = lt.driverId     WHERE d.nationality = 'Spanish'       AND strftime('%Y', d.dob) < '1982' ) SELECT     rd.forename,     rd.surname,     rd.dob,     rd.lap_time FROM ranked_drivers rd WHERE rd.rn = 1 ORDER BY rd.lap_time DESC LIMIT 10;
SELECT   r.year FROM   results AS res   JOIN races AS r     ON res.raceId = r.raceId WHERE   res.fastestLapTime IS NOT NULL ORDER BY   res.fastestLapTime ASC LIMIT 1;
SELECT     r.year FROM     races r JOIN     lapTimes lt     ON r.raceId = lt.raceId GROUP BY     r.year ORDER BY     MAX(lt.time) ASC LIMIT 1;
SELECT     driverId FROM lapTimes WHERE lap = 1 ORDER BY time ASC LIMIT 5;
SELECT COUNT(*) AS disqualified_finishers FROM results WHERE raceId > 50   AND raceId < 100   AND statusId = 2   AND time IS NOT NULL;
SELECT     COUNT(*) AS circuit_count,     c.location,     c.lat,     c.lng FROM circuits AS c WHERE c.country = 'Austria';
SELECT     r.raceId FROM     races r JOIN     results res ON r.raceId = res.raceId WHERE     res.time IS NOT NULL GROUP BY     r.raceId ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT     d.driverRef,     d.nationality,     d.dob FROM qualifying q JOIN drivers d     ON q.driverId = d.driverId WHERE     q.raceId = 23     AND q.q2 IS NOT NULL;
WITH YoungestDriver AS (     SELECT          d.driverId,         d.forename,         d.surname,         d.dob     FROM drivers d     WHERE d.dob IS NOT NULL     ORDER BY d.dob DESC     LIMIT 1 ), FirstQualifyingRace AS (     SELECT          q.raceId,         r.year,         r.name,         r.date,         r.time     FROM qualifying q     JOIN races r ON q.raceId = r.raceId     WHERE q.driverId = (SELECT driverId FROM YoungestDriver)     ORDER BY r.date ASC     LIMIT 1 ) SELECT      fqr.year,     fqr.name,     fqr.date,     fqr.time FROM FirstQualifyingRace fqr;
SELECT COUNT(*) AS count FROM drivers d JOIN results r   ON d.driverId = r.driverId JOIN status s   ON r.statusId = s.statusId WHERE d.nationality = 'American'   AND s.status = 'Puncture';
SELECT     c.url FROM constructors AS c JOIN constructorStandings AS cs     ON c.constructorId = cs.constructorId WHERE c.nationality = 'Italian' ORDER BY cs.points DESC LIMIT 1;
SELECT c.url FROM constructors c JOIN constructorStandings cs ON c.constructorId = cs.constructorId GROUP BY c.constructorId ORDER BY SUM(cs.wins) DESC LIMIT 1;
SELECT     d.forename,     d.surname FROM     lapTimes lt JOIN     drivers d     ON lt.driverId = d.driverId JOIN     races r     ON lt.raceId = r.raceId JOIN     circuits c     ON r.circuitId = c.circuitId WHERE     r.name = 'French Grand Prix'     AND lt.lap = 3 ORDER BY     lt.milliseconds DESC LIMIT 1;
SELECT     r.raceId,     lt.milliseconds FROM lapTimes AS lt JOIN races AS r   ON lt.raceId = r.raceId WHERE lt.lap = 1 ORDER BY lt.milliseconds ASC LIMIT 1;
SELECT   AVG(r.fastestLapTime) AS avg_fastest_lap_time FROM results AS r JOIN races AS ra   ON r.raceId = ra.raceId WHERE   ra.year = 2006   AND ra.name = 'United States Grand Prix'   AND r.rank < 11;
WITH german_drivers AS (     SELECT          d.driverId,         d.forename,         d.surname     FROM drivers d     WHERE d.nationality = 'German'       AND strftime('%Y', d.dob) > '1980'       AND strftime('%Y', d.dob) < '1985' ), pit_stop_stats AS (     SELECT          ps.driverId,         SUM(ps.milliseconds) * 1.0 / COUNT(ps.milliseconds) AS avg_duration_ms     FROM pitStops ps     INNER JOIN german_drivers gd ON ps.driverId = gd.driverId     GROUP BY ps.driverId ) SELECT      gd.forename,     gd.surname FROM german_drivers gd INNER JOIN pit_stop_stats pss ON gd.driverId = pss.driverId ORDER BY pss.avg_duration_ms ASC LIMIT 3;
SELECT     r.time FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Canadian Grand Prix'   AND ra.year = 2008   AND r.position = 1;
SELECT     c.constructorRef,     c.url FROM results r JOIN races ra   ON r.raceId = ra.raceId JOIN constructors c   ON r.constructorId = c.constructorId WHERE ra.year = 2009   AND ra.name = 'Singapore Grand Prix'   AND r.position = 1;
SELECT     d.forename,     d.surname,     d.dob FROM     drivers AS d WHERE     d.nationality = 'Austrian'     AND strftime('%Y', d.dob) BETWEEN '1981' AND '1991';
SELECT     d.forename || ' ' || d.surname AS full_name,     d.url AS wiki_page_link,     d.dob AS date_of_birth FROM     drivers d WHERE     d.nationality = 'German'     AND strftime('%Y', d.dob) BETWEEN '1971' AND '1985' ORDER BY     d.dob DESC;
SELECT      c.location,     c.country,     c.lat,     c.lng FROM circuits c WHERE c.name = 'Hungaroring';
SELECT     cr.points AS score,     c.name,     c.nationality FROM constructorResults cr JOIN races r     ON cr.raceId = r.raceId JOIN constructors c     ON cr.constructorId = c.constructorId WHERE r.name = 'Monaco Grand Prix'   AND r.year BETWEEN 1980 AND 2010 ORDER BY cr.points DESC LIMIT 1;
SELECT AVG(r.points) AS average_score FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton'   AND ra.name LIKE '%Turkish Grand Prix%';
SELECT AVG(races_per_year) AS annual_average_races FROM (     SELECT year, COUNT(*) AS races_per_year     FROM races     WHERE date BETWEEN '2000-01-01' AND '2010-12-31'     GROUP BY year );
SELECT nationality FROM drivers GROUP BY nationality ORDER BY COUNT(*) DESC LIMIT 1;
SELECT     COUNT(*) AS victories FROM     driverStandings WHERE     position = 91     AND wins > 0;
SELECT     r.name FROM     results AS res JOIN     races AS r     ON res.raceId = r.raceId WHERE     res.fastestLapTime IS NOT NULL ORDER BY     res.fastestLapTime ASC LIMIT 1;
SELECT      c.location || ', ' || c.country AS full_location FROM      races r JOIN      circuits c ON r.circuitId = c.circuitId ORDER BY      r.date DESC LIMIT 1;
WITH qualifying_races AS (     SELECT          r.raceId,         r.year,         c.name AS circuit_name,         ROW_NUMBER() OVER (             PARTITION BY r.year, c.name              ORDER BY r.raceId         ) AS race_number     FROM races r     JOIN circuits c ON r.circuitId = c.circuitId     WHERE r.year = 2008       AND c.name = 'Marina Bay Street Circuit' ), target_race AS (     SELECT raceId     FROM qualifying_races     WHERE race_number = 3 ), qualifying_results AS (     SELECT          q.driverId,         q.q3,         ROW_NUMBER() OVER (             ORDER BY q.q3 ASC         ) AS q3_rank     FROM qualifying q     JOIN target_race tr ON q.raceId = tr.raceId ) SELECT      d.forename,     d.surname FROM qualifying_results qr JOIN drivers d ON qr.driverId = d.driverId WHERE qr.q3_rank = 1;
WITH YoungestDriver AS (     SELECT          d.driverId,         d.forename,         d.surname,         d.nationality,         d.dob     FROM drivers d     WHERE d.dob = (SELECT MAX(dob) FROM drivers) ), FirstRace AS (     SELECT          yd.driverId,         MIN(r.raceId) AS firstRaceId     FROM YoungestDriver yd     JOIN results res ON yd.driverId = res.driverId     JOIN races r ON res.raceId = r.raceId     GROUP BY yd.driverId ) SELECT      yd.forename || ' ' || yd.surname AS full_name,     yd.nationality,     r.name AS first_race_name FROM YoungestDriver yd JOIN FirstRace fr ON yd.driverId = fr.driverId JOIN races r ON fr.firstRaceId = r.raceId;
WITH canadian_grand_prix AS (     SELECT          r.raceId,         r.name     FROM          races r     WHERE          r.name LIKE '%Canadian Grand Prix%' ), accidents_per_driver AS (     SELECT          res.driverId,         COUNT(*) AS accident_count     FROM          results res     INNER JOIN          canadian_grand_prix cgp ON res.raceId = cgp.raceId     WHERE          res.statusId = 3     GROUP BY          res.driverId ) SELECT      MAX(accident_count) AS max_accidents FROM      accidents_per_driver;
WITH oldest_driver AS (     SELECT          d.driverId,         d.forename,         d.surname,         d.dob     FROM drivers d     WHERE d.dob = (SELECT MIN(dob) FROM drivers WHERE dob IS NOT NULL) ), driver_wins AS (     SELECT          ds.driverId,         SUM(ds.wins) AS total_wins     FROM driverStandings ds     GROUP BY ds.driverId ) SELECT      dw.total_wins,     od.forename,     od.surname FROM oldest_driver od LEFT JOIN driver_wins dw ON od.driverId = dw.driverId;
SELECT MAX(duration) AS longest_time FROM pitStops;
SELECT MIN(milliseconds) AS fastest_time FROM lapTimes;
SELECT MAX(ps.duration) FROM pitStops ps JOIN drivers d ON ps.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     ps.lap FROM pitStops AS ps JOIN drivers AS d     ON ps.driverId = d.driverId JOIN races AS r     ON ps.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND r.year = 2011     AND r.name = 'Australian Grand Prix';
SELECT     ps.duration FROM pitStops AS ps JOIN races AS r     ON ps.raceId = r.raceId WHERE     r.year = 2011     AND r.name = 'Australian Grand Prix';
SELECT     MIN(lt.time) AS lap_record FROM lapTimes AS lt JOIN drivers AS d     ON lt.driverId = d.driverId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton';
WITH RankedDrivers AS (     SELECT         d.driverId,         d.forename,         d.surname,         ROW_NUMBER() OVER (ORDER BY d.driverId) AS driver_rank     FROM drivers d ), ShortestLaps AS (     SELECT         lt.driverId,         lt.time,         lt.milliseconds     FROM lapTimes lt     WHERE lt.milliseconds IS NOT NULL ), TopDrivers AS (     SELECT         rd.driverId,         rd.forename,         rd.surname     FROM RankedDrivers rd     WHERE rd.driver_rank <= 20 ), DriverShortestLaps AS (     SELECT         td.driverId,         td.forename,         td.surname,         MIN(sl.milliseconds) AS min_milliseconds     FROM TopDrivers td     JOIN ShortestLaps sl ON td.driverId = sl.driverId     GROUP BY td.driverId, td.forename, td.surname ) SELECT     dsl.forename,     dsl.surname FROM DriverShortestLaps dsl WHERE dsl.min_milliseconds = (     SELECT MIN(min_milliseconds)     FROM DriverShortestLaps );
SELECT     c.position FROM     circuits c JOIN     races r ON c.circuitId = r.circuitId JOIN     results res ON r.raceId = res.raceId JOIN     drivers d ON res.driverId = d.driverId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND res.fastestLapTime = (         SELECT MIN(res2.fastestLapTime)         FROM             results res2         JOIN             drivers d2 ON res2.driverId = d2.driverId         WHERE             d2.forename = 'Lewis'             AND d2.surname = 'Hamilton'     );
SELECT     MIN(lt.time) AS lap_record FROM lapTimes AS lt JOIN races AS r     ON lt.raceId = r.raceId JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.name = 'Austrian Grand Prix Circuit';
SELECT     c.circuitId,     c.name,     MIN(lt.milliseconds) AS fastest_lap_milliseconds,     lt.time AS fastest_lap_time FROM circuits c JOIN races r     ON c.circuitId = r.circuitId JOIN lapTimes lt     ON r.raceId = lt.raceId WHERE c.country = 'Italy' GROUP BY c.circuitId, c.name ORDER BY c.circuitId;
SELECT     r.name FROM     lapTimes AS lt JOIN     races AS r     ON lt.raceId = r.raceId JOIN     circuits AS c     ON r.circuitId = c.circuitId WHERE     c.name = 'Austrian Grand Prix Circuit' ORDER BY     lt.milliseconds ASC LIMIT 1;
WITH lap_record AS (     SELECT         lt.raceId,         lt.driverId,         lt.time AS lap_time,         lt.milliseconds     FROM lapTimes lt     JOIN races r       ON lt.raceId = r.raceId     JOIN circuits c       ON r.circuitId = c.circuitId     WHERE c.name = 'Austrian Grand Prix Circuit'     ORDER BY lt.milliseconds ASC     LIMIT 1 ) SELECT     ps.duration FROM pitStops ps JOIN lap_record lr   ON ps.raceId = lr.raceId  AND ps.driverId = lr.driverId;
SELECT     c.lat,     c.lng FROM circuits AS c JOIN races AS r   ON c.circuitId = r.circuitId JOIN lapTimes AS lt   ON r.raceId = lt.raceId WHERE lt.time = '1:29.488'   AND lt.milliseconds = (       SELECT MIN(lt2.milliseconds)       FROM lapTimes AS lt2       JOIN races AS r2         ON lt2.raceId = r2.raceId       WHERE r2.circuitId = c.circuitId   );
SELECT AVG(ps.milliseconds) FROM pitStops ps JOIN drivers d ON ps.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT AVG(lt.milliseconds) FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy';
SELECT p.player_api_id FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT     p.height,     p.player_name FROM Player AS p ORDER BY p.height DESC LIMIT 1;
SELECT preferred_foot FROM Player_Attributes ORDER BY potential ASC LIMIT 1;
SELECT COUNT(*) FROM Player_Attributes WHERE overall_rating >= 60   AND overall_rating < 65   AND defensive_work_rate = 'low';
SELECT     p.id FROM Player p JOIN Player_Attributes pa     ON p.player_api_id = pa.player_api_id GROUP BY     p.id,     p.player_api_id ORDER BY     MAX(pa.crossing) DESC LIMIT 5;
SELECT     l.name FROM Match AS m JOIN League AS l     ON m.league_id = l.id WHERE     m.season = '2015/2016' GROUP BY     l.id,     l.name ORDER BY     SUM(m.home_team_goal + m.away_team_goal) DESC LIMIT 1;
SELECT     t.team_long_name FROM Match m JOIN Team t     ON m.home_team_api_id = t.team_api_id WHERE     m.season = '2015/2016'     AND m.home_team_goal < m.away_team_goal GROUP BY     t.team_long_name ORDER BY     COUNT(*) ASC LIMIT 1;
SELECT     p.player_name FROM     Player p JOIN     Player_Attributes pa ON p.player_api_id = pa.player_api_id GROUP BY     p.player_api_id,     p.player_name ORDER BY     MAX(pa.penalties) DESC LIMIT 10;
SELECT     T.team_long_name FROM     Match AS M     JOIN League AS L ON M.league_id = L.id     JOIN Team AS T ON M.away_team_api_id = T.team_api_id WHERE     L.name = 'Scotland Premier League'     AND M.season = '2009/2010'     AND M.away_team_goal > M.home_team_goal GROUP BY     T.team_long_name ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT     T1.buildUpPlaySpeed FROM Team_Attributes AS T1 ORDER BY     T1.buildUpPlaySpeed DESC LIMIT 4;
SELECT     l.name FROM     Match m JOIN     League l     ON m.league_id = l.id WHERE     m.season = '2015/2016' GROUP BY     l.name ORDER BY     SUM(CASE WHEN m.home_team_goal = m.away_team_goal THEN 1 ELSE 0 END) DESC LIMIT 1;
SELECT     CAST(         (julianday('now') - julianday(p.birthday)) / 365.25         AS INTEGER     ) AS age FROM Player p JOIN Player_Attributes pa     ON p.player_api_id = pa.player_api_id WHERE     pa.sprint_speed >= 97     AND strftime('%Y', pa.date) >= '2013'     AND strftime('%Y', pa.date) <= '2015';
SELECT     L.name,     COUNT(M.id) AS match_count FROM League AS L JOIN Match AS M     ON L.id = M.league_id GROUP BY     L.id,     L.name ORDER BY     match_count DESC LIMIT 1;
SELECT      SUM(height) * 1.0 / COUNT(id) AS average_height FROM      Player WHERE      birthday >= '1990-01-01 00:00:00'      AND birthday < '1996-01-01 00:00:00';
SELECT     player_api_id FROM     Player_Attributes WHERE     substr(date, 1, 4) = '2010'     AND overall_rating = (         SELECT             MAX(overall_rating)         FROM             Player_Attributes         WHERE             substr(date, 1, 4) = '2010'     );
SELECT     team_fifa_api_id FROM Team_Attributes WHERE buildUpPlaySpeed > 50   AND buildUpPlaySpeed < 60;
WITH AvgPassing AS (     SELECT          AVG(buildUpPlayPassing) AS avg_passing     FROM Team_Attributes     WHERE strftime('%Y', date) = '2012'       AND buildUpPlayPassing IS NOT NULL ) SELECT DISTINCT t.team_long_name FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id CROSS JOIN AvgPassing ap WHERE strftime('%Y', ta.date) = '2012'   AND ta.buildUpPlayPassing IS NOT NULL   AND ta.buildUpPlayPassing > ap.avg_passing;
SELECT      CAST(SUM(CASE WHEN pa.preferred_foot = 'left' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(pa.player_fifa_api_id) AS percentage FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE strftime('%Y', p.birthday) BETWEEN '1987' AND '1992';
SELECT     l.name AS league_name,     SUM(m.home_team_goal + m.away_team_goal) AS total_goals FROM League l JOIN Match m ON l.id = m.league_id GROUP BY l.id, l.name ORDER BY total_goals ASC LIMIT 5;
SELECT     SUM(pa.long_shots) * 1.0 / COUNT(pa.player_fifa_api_id) AS average_long_shots FROM Player_Attributes pa JOIN Player p     ON pa.player_fifa_api_id = p.player_fifa_api_id WHERE p.player_name = 'Ahmed Samir Farag';
SELECT     p.player_name FROM     Player p JOIN     Player_Attributes pa         ON p.player_fifa_api_id = pa.player_fifa_api_id WHERE     p.height > 180 GROUP BY     p.player_name ORDER BY     SUM(pa.heading_accuracy) * 1.0 / COUNT(pa.player_fifa_api_id) DESC LIMIT 10;
WITH cte AS (     SELECT         t.team_long_name,         ta.chanceCreationPassing     FROM Team_Attributes ta     JOIN Team t ON ta.team_api_id = t.team_api_id     WHERE ta.buildUpPlayDribblingClass = 'Normal'       AND ta.date >= '2014-01-01 00:00:00'       AND ta.date <= '2014-01-31 00:00:00' ), avg_cte AS (     SELECT         AVG(chanceCreationPassing) AS avg_passing     FROM cte ) SELECT     c.team_long_name FROM cte c CROSS JOIN avg_cte a WHERE c.chanceCreationPassing < a.avg_passing ORDER BY c.chanceCreationPassing DESC;
SELECT     L.name FROM     League L JOIN     Match M     ON L.id = M.league_id WHERE     M.season = '2009/2010' GROUP BY     L.id,     L.name HAVING     SUM(M.home_team_goal) / COUNT(DISTINCT M.id) >     SUM(M.away_team_goal) / COUNT(DISTINCT M.id);
SELECT team_short_name FROM Team WHERE team_long_name = 'Queens Park Rangers';
SELECT     p.player_name FROM     Player p WHERE     substr(p.birthday, 1, 4) = '1970'     AND substr(p.birthday, 6, 2) = '10';
SELECT     pa.attacking_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Franco Zennaro';
SELECT     ta.buildUpPlayPositioningClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'ADO Den Haag';
SELECT     pa.heading_accuracy FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Francois Affolter'     AND pa.date = '2014-09-18 00:00:00';
SELECT     pa.overall_rating FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Gabriel Tamas'     AND strftime('%Y', pa.date) = '2011';
SELECT COUNT(*) AS match_count FROM Match m JOIN League l ON m.league_id = l.id WHERE m.season = '2015/2016'   AND l.name = 'Scotland Premier League';
SELECT     pa.preferred_foot FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id ORDER BY p.birthday DESC LIMIT 1;
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.potential = (SELECT MAX(potential) FROM Player_Attributes);
SELECT COUNT(*) FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.weight < 130   AND pa.preferred_foot = 'left';
SELECT DISTINCT T.team_short_name FROM Team T JOIN Team_Attributes TA ON T.team_api_id = TA.team_api_id WHERE TA.chanceCreationPassingClass = 'Risky';
SELECT     pa.defensive_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'David Wilson';
SELECT p.birthday FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT l.name FROM League l JOIN Country c ON l.country_id = c.id WHERE c.name = 'Netherlands';
SELECT AVG(m.home_team_goal) AS average_home_team_goal FROM Match m JOIN Country c ON m.country_id = c.id WHERE c.name = 'Poland'   AND m.season = '2010/2011';
WITH HeightRange AS (     SELECT          MIN(height) AS min_height,         MAX(height) AS max_height     FROM Player ), PlayersInRange AS (     SELECT          p.player_api_id,         p.player_name,         pa.finishing     FROM Player p     JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id     CROSS JOIN HeightRange hr     WHERE p.height BETWEEN hr.min_height AND hr.max_height ), AvgFinishing AS (     SELECT          player_api_id,         player_name,         AVG(finishing) AS avg_finishing     FROM PlayersInRange     GROUP BY player_api_id, player_name ) SELECT      player_name FROM AvgFinishing ORDER BY avg_finishing DESC LIMIT 1;
SELECT player_name FROM Player WHERE height > 180;
SELECT COUNT(*) AS player_count FROM Player WHERE strftime('%Y', birthday) = '1990';
SELECT COUNT(*) FROM Player WHERE player_name LIKE 'Adam%'   AND weight > 170;
SELECT DISTINCT p.player_name FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE pa.overall_rating > 80   AND strftime('%Y', pa.date) BETWEEN '2008' AND '2010';
SELECT pa.potential FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Aaron Doran';
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.preferred_foot = 'left';
SELECT DISTINCT t.team_long_name FROM Team t JOIN Team_Attributes ta ON t.team_api_id = ta.team_api_id WHERE ta.buildUpPlaySpeedClass = 'Fast';
SELECT     ta.buildUpPlayPassingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE t.team_short_name = 'CLB';
SELECT DISTINCT t.team_short_name FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE ta.buildUpPlayPassing > 70;
SELECT     SUM(pa.overall_rating) / COUNT(pa.id) AS average_overall_rating FROM Player_Attributes pa JOIN Player p     ON pa.player_api_id = p.player_api_id WHERE     strftime('%Y', pa.date) >= '2010'     AND strftime('%Y', pa.date) <= '2015'     AND p.height > 170;
SELECT player_name FROM Player ORDER BY height ASC LIMIT 1;
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Italy Serie A';
SELECT     t.team_short_name FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     ta.buildUpPlaySpeed = 31     AND ta.buildUpPlayDribbling = 53     AND ta.buildUpPlayPassing = 32;
SELECT AVG(pa.overall_rating) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Aaron Doran';
SELECT COUNT(*) FROM Match m JOIN League l ON m.league_id = l.id WHERE l.name = 'Germany 1. Bundesliga'   AND strftime('%Y-%m', m.date) BETWEEN '2008-08' AND '2008-10';
SELECT T.team_short_name FROM Team AS T JOIN Match AS M ON T.team_api_id = M.home_team_api_id WHERE M.home_team_goal = 10;
SELECT     p.player_name FROM Player p JOIN Player_Attributes pa     ON p.player_api_id = pa.player_api_id WHERE pa.potential = 61   AND pa.balance = (       SELECT MAX(balance)       FROM Player_Attributes       WHERE potential = 61   );
SELECT      AVG(CASE WHEN p.player_name = 'Abdou Diallo' THEN pa.ball_control ELSE NULL END) -     AVG(CASE WHEN p.player_name = 'Aaron Appindangoye' THEN pa.ball_control ELSE NULL END) AS difference FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name IN ('Abdou Diallo', 'Aaron Appindangoye');
SELECT team_long_name FROM Team WHERE team_short_name = 'GEN';
SELECT     p.player_name FROM     Player p WHERE     p.player_name IN ('Aaron Lennon', 'Abdelaziz Barrada') ORDER BY     p.birthday DESC LIMIT 1;
SELECT player_name FROM Player ORDER BY height DESC LIMIT 1;
SELECT COUNT(*) FROM Player_Attributes WHERE preferred_foot = 'left'   AND attacking_work_rate = 'low';
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Belgium Jupiler League';
SELECT l.name FROM League l JOIN Country c ON l.country_id = c.id WHERE c.name = 'Germany';
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT     COUNT(DISTINCT p.player_api_id) AS player_count FROM     Player p JOIN     Player_Attributes pa         ON p.player_api_id = pa.player_api_id WHERE     strftime('%Y', p.birthday) < '1986'     AND pa.defensive_work_rate = 'high';
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name IN ('Alexis', 'Ariel Borysiuk', 'Arouna Kone') GROUP BY p.player_name ORDER BY MAX(pa.crossing) DESC LIMIT 1;
SELECT pa.heading_accuracy FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Ariel Borysiuk';
SELECT COUNT(DISTINCT p.player_api_id) AS player_count FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.height > 180   AND pa.volleys > 70;
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.volleys > 70   AND pa.dribbling > 70;
SELECT COUNT(*) FROM Match m JOIN Country c ON m.country_id = c.id WHERE c.name = 'Belgium'   AND m.season = '2008/2009';
SELECT pa.long_passing FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY p.birthday ASC LIMIT 1;
SELECT COUNT(*) AS match_count FROM Match m JOIN League l ON m.league_id = l.id WHERE l.name = 'Belgium Jupiler League'   AND SUBSTR(m.date, 1, 7) = '2009-04';
SELECT     l.name FROM League AS l JOIN Match AS m     ON l.id = m.league_id WHERE     m.season = '2008/2009' GROUP BY     l.id,     l.name ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT     CAST(SUM(pa.overall_rating) AS REAL) / COUNT(pa.id) AS average_overall_rating FROM Player_Attributes pa JOIN Player p     ON pa.player_api_id = p.player_api_id WHERE strftime('%Y', p.birthday) < '1986';
SELECT      (         (             (                 SELECT pa.overall_rating                 FROM Player_Attributes pa                 JOIN Player p ON pa.player_api_id = p.player_api_id                 WHERE p.player_name = 'Ariel Borysiuk'                 LIMIT 1             )             -             (                 SELECT pa.overall_rating                 FROM Player_Attributes pa                 JOIN Player p ON pa.player_api_id = p.player_api_id                 WHERE p.player_name = 'Paulin Puel'                 LIMIT 1             )         )         * 100.0         /         (             SELECT pa.overall_rating             FROM Player_Attributes pa             JOIN Player p ON pa.player_api_id = p.player_api_id             WHERE p.player_name = 'Paulin Puel'             LIMIT 1         )     ) AS percentage_difference;
SELECT AVG(T1.buildUpPlaySpeed) AS average_build_up_play_speed FROM Team_Attributes AS T1 INNER JOIN Team AS T2   ON T1.team_api_id = T2.team_api_id WHERE T2.team_long_name = 'Heart of Midlothian';
SELECT AVG(pa.overall_rating) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Pietro Marino';
SELECT SUM(pa.crossing) AS total_crossing_score FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Aaron Lennox';
SELECT     MAX(ta.chanceCreationPassing) AS highest_chance_creation_passing,     ta.chanceCreationPassingClass AS chance_creation_passing_class FROM Team_Attributes ta JOIN Team t     ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'Ajax' ORDER BY ta.chanceCreationPassing DESC LIMIT 1;
SELECT pa.preferred_foot FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Abdou Diallo';
SELECT MAX(pa.overall_rating) FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Dorlan Pabon';
SELECT AVG(m.away_team_goal) AS average_goals FROM Match m JOIN Team t ON m.away_team_api_id = t.team_api_id JOIN Country c ON m.country_id = c.id WHERE t.team_long_name = 'Parma'   AND c.name = 'Italy';
SELECT     p.player_name FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     pa.overall_rating = 77     AND pa.date LIKE '2016-06-23%' ORDER BY     p.birthday ASC LIMIT 1;
SELECT     pa.overall_rating FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Aaron Mooy'     AND pa.date LIKE '2016-02-04%';
SELECT     pa.potential FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Francesco Parravicini'     AND pa.date = '2010-08-30 00:00:00';
SELECT     pa.attacking_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Francesco Migliore'     AND pa.date LIKE '2015-05-01%';
SELECT     pa.defensive_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Kevin Berigaud'     AND pa.date = '2013-02-22 00:00:00';
SELECT     pa.date FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Kevin Constant'     AND pa.crossing = (         SELECT MAX(pa2.crossing)         FROM Player_Attributes AS pa2         JOIN Player AS p2             ON pa2.player_api_id = p2.player_api_id         WHERE             p2.player_name = 'Kevin Constant'     ) ORDER BY     pa.date ASC LIMIT 1;
SELECT     ta.buildUpPlaySpeedClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'Willem II'     AND ta.date = '2012-02-22';
SELECT     ta.buildUpPlayDribblingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_short_name = 'LEI'     AND ta.date = '2015-09-10 00:00:00';
SELECT     ta.buildUpPlayPassingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'FC Lorient'     AND ta.date LIKE '2010-02-22%';
SELECT     ta.chanceCreationPassingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'PEC Zwolle'     AND ta.date = '2013-09-20 00:00:00';
SELECT     ta.chanceCreationCrossingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'Hull City'     AND ta.date = '2010-02-22 00:00:00';
SELECT     ta.defenceAggressionClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'Hannover 96'     AND ta.date LIKE '2015-09-10%';
SELECT AVG(pa.overall_rating) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Marko Arnautovic'   AND substr(pa.date, 1, 10) BETWEEN '2007-02-22' AND '2016-04-21';
SELECT      CAST((pa1.overall_rating - pa2.overall_rating) AS REAL) * 100 / pa1.overall_rating AS percentage FROM Player_Attributes pa1 JOIN Player p1 ON pa1.player_api_id = p1.player_api_id JOIN Player_Attributes pa2 ON pa2.date = pa1.date JOIN Player p2 ON pa2.player_api_id = p2.player_api_id WHERE p1.player_name = 'Landon Donovan'   AND p2.player_name = 'Jordan Bowery'   AND pa1.date = '2013-07-12';
WITH RankedPlayers AS (     SELECT          player_name,         RANK() OVER (ORDER BY height DESC) AS height_rank     FROM Player ) SELECT player_name FROM RankedPlayers WHERE height_rank = 1;
SELECT player_api_id FROM Player ORDER BY weight DESC LIMIT 10;
SELECT p.player_name FROM Player p WHERE (julianday('now') - julianday(p.birthday)) / 365.25 >= 35;
SELECT     SUM(m.home_team_goal) FROM Match AS m JOIN Player AS p     ON m.home_player_1 = p.player_api_id    OR m.home_player_2 = p.player_api_id    OR m.home_player_3 = p.player_api_id    OR m.home_player_4 = p.player_api_id    OR m.home_player_5 = p.player_api_id    OR m.home_player_6 = p.player_api_id    OR m.home_player_7 = p.player_api_id    OR m.home_player_8 = p.player_api_id    OR m.home_player_9 = p.player_api_id    OR m.home_player_10 = p.player_api_id    OR m.home_player_11 = p.player_api_id WHERE p.player_name = 'Aaron Lennon';
SELECT     SUM(CASE             WHEN p1.player_name = 'Daan Smith' THEN m.away_team_goal             WHEN p1.player_name = 'Filipe Ferreira' THEN m.away_team_goal             ELSE 0         END) AS total_away_goals FROM Match m JOIN Player p1     ON m.away_player_1 = p1.player_api_id    OR m.away_player_2 = p1.player_api_id    OR m.away_player_3 = p1.player_api_id    OR m.away_player_4 = p1.player_api_id    OR m.away_player_5 = p1.player_api_id    OR m.away_player_6 = p1.player_api_id    OR m.away_player_7 = p1.player_api_id    OR m.away_player_8 = p1.player_api_id    OR m.away_player_9 = p1.player_api_id    OR m.away_player_10 = p1.player_api_id    OR m.away_player_11 = p1.player_api_id WHERE p1.player_name IN ('Daan Smith', 'Filipe Ferreira');
SELECT   SUM(m.home_team_goal) AS total_home_goals FROM Match AS m WHERE m.home_player_1 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_2 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_3 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_4 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_5 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_6 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_7 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_8 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_9 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_10 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   )    OR m.home_player_11 IN (     SELECT p.player_api_id     FROM Player AS p     WHERE julianday('now') - julianday(p.birthday) <= 30 * 365   );
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.potential = (SELECT MAX(potential) FROM Player_Attributes);
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.attacking_work_rate = 'high';
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.finishing = 1 ORDER BY p.birthday ASC LIMIT 1;
SELECT DISTINCT p.player_name FROM Player p JOIN Match m   ON p.player_api_id IN (        m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,        m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,        m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,        m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11      ) JOIN Country c ON m.country_id = c.id WHERE c.name = 'Belgium';
SELECT DISTINCT     p.player_name,     c.name AS country FROM Player_Attributes pa JOIN Player p     ON pa.player_api_id = p.player_api_id JOIN Match m     ON p.player_api_id IN (         m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,         m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,         m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,         m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11     ) JOIN Country c     ON m.country_id = c.id WHERE pa.vision > 89;
SELECT      c.name AS country_name,     AVG(p.weight) AS average_weight FROM      Player p JOIN      Match m ON p.player_api_id IN (         m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,         m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,         m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,         m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11     ) JOIN      Country c ON m.country_id = c.id GROUP BY      c.name ORDER BY      average_weight DESC LIMIT 1;
SELECT DISTINCT t.team_long_name FROM Team t JOIN Team_Attributes ta ON t.team_api_id = ta.team_api_id WHERE ta.buildUpPlaySpeedClass = 'Slow';
SELECT DISTINCT T.team_short_name FROM Team_Attributes TA JOIN Team T   ON TA.team_api_id = T.team_api_id WHERE TA.chanceCreationPassingClass = 'Safe';
SELECT AVG(p.height) AS average_height FROM Player p JOIN Match m   ON p.player_api_id IN (        m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,        m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,        m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,        m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11      ) JOIN Country c   ON m.country_id = c.id WHERE c.name = 'Italy';
SELECT player_name FROM Player WHERE height > 180 ORDER BY player_name ASC LIMIT 3;
SELECT COUNT(*) AS count FROM Player WHERE player_name LIKE 'Aaron%'   AND birthday > '1990';
SELECT      (SELECT jumping FROM Player_Attributes WHERE id = 6) -      (SELECT jumping FROM Player_Attributes WHERE id = 23) AS difference;
SELECT     p.id FROM Player p JOIN Player_Attributes pa     ON p.player_api_id = pa.player_api_id WHERE pa.preferred_foot = 'right' ORDER BY     pa.potential ASC,     p.id ASC LIMIT 5;
SELECT COUNT(*) FROM Player_Attributes WHERE preferred_foot = 'left'   AND crossing = (     SELECT MAX(crossing)     FROM Player_Attributes     WHERE preferred_foot = 'left'   );
SELECT      CAST(SUM(CASE WHEN stamina > 80 AND strength > 80 THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM Player_Attributes;
SELECT DISTINCT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Poland Ekstraklasa';
SELECT     m.home_team_goal,     m.away_team_goal FROM Match AS m JOIN League AS l     ON m.league_id = l.id WHERE     m.date LIKE '2008-09-24%'     AND l.name = 'Belgium Jupiler League';
SELECT     pa.sprint_speed,     pa.agility,     pa.acceleration FROM Player_Attributes pa JOIN Player p     ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Alexis Blin';
SELECT DISTINCT     ta.buildUpPlaySpeedClass FROM Team_Attributes ta JOIN Team t     ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'KSV Cercle Brugge';
SELECT COUNT(*) AS game_count FROM Match m JOIN League l ON m.league_id = l.id WHERE m.season = '2015/2016'   AND l.name = 'Italy Serie A';
SELECT MAX(m.home_team_goal) AS highest_home_score FROM Match m JOIN League l ON m.league_id = l.id JOIN Country c ON l.country_id = c.id WHERE l.name = 'Netherlands Eredivisie';
SELECT     pa.finishing,     pa.curve FROM Player p JOIN Player_Attributes pa     ON p.player_api_id = pa.player_api_id WHERE p.weight = (     SELECT MAX(weight)     FROM Player );
SELECT     l.name FROM Match AS m JOIN League AS l     ON m.league_id = l.id WHERE     m.season = '2015/2016' GROUP BY     l.name ORDER BY     COUNT(m.id) DESC LIMIT 4;
SELECT     T.team_long_name FROM Match AS M JOIN Team AS T     ON M.away_team_api_id = T.team_api_id ORDER BY     M.away_team_goal DESC LIMIT 1;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT   CAST(COUNT(CASE WHEN p.height < 180 AND pa.overall_rating > 70 THEN 1 END) AS REAL) * 100 / COUNT(p.id) AS percentage FROM Player p JOIN Player_Attributes pa   ON p.player_api_id = pa.player_api_id;
WITH male_counts AS (     SELECT          SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) AS in_patient_count,         SUM(CASE WHEN Admission = '-' THEN 1 ELSE 0 END) AS out_patient_count     FROM Patient     WHERE SEX = 'M' ) SELECT      CASE          WHEN in_patient_count > out_patient_count THEN 'in-patient'         WHEN out_patient_count > in_patient_count THEN 'outpatient'         ELSE 'equal'     END AS category,     ABS(in_patient_count - out_patient_count) * 100.0 / NULLIF(out_patient_count, 0) AS deviation_percentage FROM male_counts;
SELECT      CAST(SUM(CASE WHEN strftime('%Y', Birthday) > '1930' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(ID) AS percentage FROM      Patient WHERE      SEX = 'F';
SELECT      CAST(SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM      Patient WHERE      Birthday BETWEEN '1930-01-01' AND '1940-12-31';
SELECT      CAST(SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) AS REAL) * 1.0 /      NULLIF(SUM(CASE WHEN Admission = '-' THEN 1 ELSE 0 END), 0) AS ratio FROM      Patient WHERE      Diagnosis = 'SLE';
SELECT     p.Diagnosis,     l.Date FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.ID = 30609;
SELECT      p.SEX,     p.Birthday,     e.`Examination Date`,     e.Symptoms FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p.ID = 163109;
SELECT DISTINCT     p.ID,     p.SEX,     p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.LDH > 500;
SELECT     p.ID,     CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient AS p JOIN Examination AS e     ON p.ID = e.ID WHERE e.RVVT = '+';
SELECT DISTINCT     p.ID,     p.SEX,     p.Diagnosis FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE e.Thrombosis = 2;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE strftime('%Y', p.Birthday) = '1937'   AND l.`T-CHO` >= 250;
SELECT DISTINCT p.ID, p.SEX, p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.ALB < 3.5;
SELECT      CAST(SUM(CASE WHEN T1.SEX = 'F' AND (T2.TP < 6.0 OR T2.TP > 8.5) THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.ID) AS percentage FROM      Patient T1 JOIN      Laboratory T2 ON T1.ID = T2.ID;
SELECT AVG(e.`aCL IgG`) AS average_acl_igg FROM Examination e JOIN Patient p ON e.ID = p.ID WHERE p.Admission = '+'   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) >= 50;
SELECT COUNT(*) AS count FROM Patient WHERE SEX = 'F'   AND STRFTIME('%Y', Description) = '1997'   AND Admission = '-';
SELECT MIN(SUBSTR(`First Date`, 1, 4) - SUBSTR(Birthday, 1, 4)) AS age FROM Patient WHERE `First Date` IS NOT NULL   AND Birthday IS NOT NULL;
SELECT COUNT(*) AS count FROM Examination AS e JOIN Patient AS p   ON e.ID = p.ID WHERE e.Thrombosis = 1   AND strftime('%Y', e.`Examination Date`) = '1997'   AND p.SEX = 'F';
SELECT MAX(CAST(STRFTIME('%Y', P.Birthday) AS INTEGER)) - MIN(CAST(STRFTIME('%Y', P.Birthday) AS INTEGER)) AS age_gap FROM Patient P JOIN Laboratory L ON P.ID = L.ID WHERE L.TG >= 200;
SELECT     e.Symptoms,     e.Diagnosis FROM Examination e JOIN Patient p   ON e.ID = p.ID WHERE e.Symptoms IS NOT NULL ORDER BY p.Birthday DESC LIMIT 1;
SELECT   CAST(COUNT(DISTINCT l.ID) AS REAL) / 12 AS average_male_patients_per_month FROM Laboratory l JOIN Patient p   ON l.ID = p.ID WHERE p.SEX = 'M'   AND l.Date BETWEEN '1998-01-01' AND '1998-12-31';
SELECT      l.Date,     (strftime('%Y', p.`First Date`) - strftime('%Y', p.Birthday)) AS age FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Diagnosis = 'SJS' ORDER BY p.Birthday DESC LIMIT 1;
SELECT      CAST(SUM(CASE WHEN p.SEX = 'M' AND l.UA <= 8.0 THEN 1 ELSE 0 END) AS REAL) * 1.0 /      NULLIF(SUM(CASE WHEN p.SEX = 'F' AND l.UA <= 6.5 THEN 1 ELSE 0 END), 0) AS ratio FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE (p.SEX = 'M' AND l.UA <= 8.0) OR (p.SEX = 'F' AND l.UA <= 6.5);
SELECT COUNT(*) FROM Patient p LEFT JOIN Examination e ON p.ID = e.ID WHERE e.ID IS NULL    OR (CAST(strftime('%Y', e.`Examination Date`) AS INTEGER) - CAST(strftime('%Y', p.`First Date`) AS INTEGER)) >= 1;
SELECT COUNT(*) FROM Examination AS e JOIN Patient AS p   ON e.ID = p.ID WHERE strftime('%Y', p.Birthday) < '18'   AND strftime('%Y', e.`Examination Date`) BETWEEN '1990' AND '1993';
SELECT COUNT(*) AS count FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.`T-BIL` >= 2.0;
SELECT     e.Diagnosis FROM Examination AS e WHERE     e.`Examination Date` BETWEEN '1985-01-01' AND '1995-12-31' GROUP BY     e.Diagnosis ORDER BY     COUNT(e.Diagnosis) DESC LIMIT 1;
SELECT AVG(1999 - CAST(strftime('%Y', p.Birthday) AS INTEGER)) AS average_age FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.Date BETWEEN '1991-10-01' AND '1991-10-30';
SELECT     (strftime('%Y', e.`Examination Date`) - strftime('%Y', p.Birthday)) AS age,     p.Diagnosis FROM Examination e JOIN Patient p ON e.ID = p.ID JOIN Laboratory l ON e.ID = l.ID AND e.`Examination Date` = l.Date WHERE l.HGB = (     SELECT MAX(l2.HGB)     FROM Laboratory l2     JOIN Examination e2 ON l2.ID = e2.ID AND l2.Date = e2.`Examination Date` ) LIMIT 1;
SELECT ANA FROM Examination WHERE ID = 3605340   AND `Examination Date` = '1996-12-02';
SELECT      CASE          WHEN T1.`T-CHO` < 250 THEN 'Yes'          ELSE 'No'      END AS `Is Normal` FROM      `Laboratory` T1 WHERE      T1.`ID` = 2927464      AND T1.`Date` = '1995-09-04';
SELECT     p.SEX FROM     Patient p JOIN     Examination e     ON p.ID = e.ID WHERE     e.Diagnosis = 'AORTITIS' ORDER BY     e.`Examination Date` ASC LIMIT 1;
SELECT     e.`aCL IgM` FROM     Examination e JOIN     Patient p     ON e.ID = p.ID WHERE     p.`Diagnosis` = 'SLE'     AND p.`Description` = '1994-02-19'     AND e.`Examination Date` = '1993-11-12';
SELECT   p.SEX FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE   l.Date = '1992-06-12'   AND l.GPT = 9;
SELECT     CAST(strftime('%Y', l.Date) AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Laboratory AS l JOIN Patient AS p     ON l.ID = p.ID WHERE     l.UA = 8.4     AND l.Date = '1991-10-21';
SELECT COUNT(l.ID) AS total_laboratory_tests FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.`First Date` = '1991-06-13'   AND p.Diagnosis = 'SJS'   AND l.Date LIKE '1995%';
SELECT     p.Diagnosis FROM Patient AS p JOIN Examination AS e   ON p.ID = e.ID WHERE     e.`Examination Date` = '1997-01-27'     AND e.Diagnosis = 'SLE';
SELECT e.Symptoms FROM Examination e JOIN Patient p ON e.ID = p.ID WHERE p.Birthday = '1959-03-01'   AND e.`Examination Date` = '1993-09-27';
SELECT      SUM(CASE WHEN p.Birthday = '1959-02-18' AND l.Date LIKE '1981-11-%' THEN l.`T-CHO` ELSE 0 END) -     SUM(CASE WHEN p.Birthday = '1959-02-18' AND l.Date LIKE '1981-12-%' THEN l.`T-CHO` ELSE 0 END) AS decrease_rate FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday = '1959-02-18'   AND (l.Date LIKE '1981-11-%' OR l.Date LIKE '1981-12-%');
SELECT DISTINCT p.ID FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p.Diagnosis = 'Behcet'   AND e.`Examination Date` >= '1997-01-01'   AND e.`Examination Date` < '1998-01-01';
SELECT DISTINCT l.ID FROM Laboratory l WHERE l.Date BETWEEN '1987-07-06' AND '1996-01-31'   AND l.GPT > 30   AND l.ALB < 4;
SELECT COUNT(*) AS count, ID FROM Patient WHERE SEX = 'F'   AND strftime('%Y', Birthday) = '1964'   AND Admission = '+' GROUP BY ID;
SELECT COUNT(*) FROM Examination WHERE Thrombosis = 2   AND `ANA Pattern` = 'S'   AND `aCL IgM` > (SELECT AVG(`aCL IgM`) FROM Examination) * 1.2;
SELECT      CAST(SUM(CASE WHEN UA <= 6.5 THEN 1 ELSE 0 END) AS REAL) * 100 /      CAST(SUM(CASE WHEN U-PRO > 0 AND U-PRO < 30 THEN 1 ELSE 0 END) AS REAL) AS percentage FROM Laboratory WHERE U-PRO > 0 AND U-PRO < 30;
SELECT      CAST(SUM(CASE WHEN p.Diagnosis = 'BEHCET' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM Patient p WHERE p.SEX = 'M'    AND strftime('%Y', p.`First Date`) = '1981';
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.Date LIKE '1991-10%'   AND l.`T-BIL` < 2.0;
SELECT COUNT(*) AS count FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE e.`ANA Pattern` != 'P'   AND p.SEX = 'F'   AND p.Birthday BETWEEN '1980-01-01' AND '1989-12-31';
SELECT     p.SEX FROM Patient AS p JOIN Examination AS e     ON p.ID = e.ID JOIN Laboratory AS l     ON p.ID = l.ID WHERE     e.Diagnosis = 'PSS'     AND l.CRP = '2+'     AND l.CRE = 1     AND l.LDH = 123;
SELECT AVG(l.ALB) AS average_alb FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE p.SEX = 'F'   AND l.PLT > 400   AND p.Diagnosis = 'SLE';
SELECT e.Symptoms FROM Examination e JOIN Patient p ON e.ID = p.ID WHERE p.Diagnosis = 'SLE' GROUP BY e.Symptoms ORDER BY COUNT(e.Symptoms) DESC LIMIT 1;
SELECT      p.`Description` AS first_documented_date,     p.`Diagnosis` AS disease FROM      `Patient` p WHERE      p.`ID` = 48473;
SELECT COUNT(*) AS count FROM Patient WHERE SEX = 'F'   AND Diagnosis = 'APS';
SELECT COUNT(DISTINCT L.ID) AS patient_count FROM Laboratory L WHERE STRFTIME('%Y', L.Date) = '1997'   AND (L.TP <= 6 OR L.TP >= 8.5);
SELECT      CAST(SUM(CASE WHEN e.Diagnosis LIKE '%SLE%' THEN 1 ELSE 0 END) AS REAL) * 100 /      SUM(CASE WHEN e.Symptoms LIKE '%thrombocytopenia%' THEN 1 ELSE 0 END) AS proportion FROM Examination e WHERE e.Symptoms LIKE '%thrombocytopenia%';
SELECT      CAST(SUM(CASE WHEN p.SEX = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(p.SEX) AS percentage FROM      Patient p WHERE      strftime('%Y', p.Birthday) = '1980'     AND p.Diagnosis = 'RA';
SELECT COUNT(*) AS count FROM Patient AS p JOIN Examination AS e   ON p.ID = e.ID WHERE p.SEX = 'M'   AND e.`Examination Date` BETWEEN '1995-01-01' AND '1997-12-31'   AND e.Diagnosis = 'Behcet'   AND p.Admission = '-';
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'F'   AND l.WBC < 3.5;
SELECT      DATEDIFF(e.`Examination Date`, p.`First Date`) AS days_between FROM      Patient p JOIN      Examination e ON p.ID = e.ID WHERE      p.ID = 821298;
SELECT   CASE     WHEN (p.SEX = 'M' AND l.UA > 8.0) OR (p.SEX = 'F' AND l.UA > 6.5) THEN 'Yes'     ELSE 'No'   END AS is_within_normal_range FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.ID = 57266;
SELECT     L."Date" FROM     Laboratory AS L WHERE     L.ID = 48473     AND L.GOT >= 60;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.GOT < 60   AND strftime('%Y', l.Date) = '1994';
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.GPT >= 60;
SELECT     p.Diagnosis FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     l.GPT > 60 ORDER BY     p.Birthday ASC;
SELECT AVG(LDH) AS average_ldh FROM Laboratory WHERE LDH < 500;
SELECT     p.ID,     CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.LDH BETWEEN 600 AND 800;
SELECT     CASE         WHEN p.Admission = '+' THEN 'inpatient'         WHEN p.Admission = '-' THEN 'outpatient'         ELSE 'unknown'     END AS admission_type FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.ALP < 300;
SELECT   p.ID FROM Patient AS p WHERE p.Birthday = '1982-04-01';
SELECT DISTINCT     p.ID,     p.SEX,     p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TP < 6.0;
SELECT     T1.ID,     T2.TP - 8.5 AS deviation FROM     Patient AS T1 JOIN     Laboratory AS T2     ON T1.ID = T2.ID WHERE     T1.SEX = 'F'     AND T2.TP > 8.5;
SELECT     p.ID,     p.SEX,     p.Birthday,     p.Description,     p.`First Date`,     p.Admission,     p.Diagnosis FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     p.SEX = 'M'     AND (l.ALB <= 3.5 OR l.ALB >= 5.5) ORDER BY     p.Birthday DESC;
SELECT      p.ID,     CASE          WHEN l.ALB BETWEEN 3.5 AND 5.5 THEN 'Yes'         ELSE 'No'     END AS is_alb_within_normal_range FROM Patient p LEFT JOIN Laboratory l ON p.ID = l.ID WHERE strftime('%Y', p.Birthday) = '1982';
SELECT      CAST(SUM(CASE WHEN T1.UA > 6.5 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM      Laboratory T1 JOIN      Patient T2 ON      T1.ID = T2.ID WHERE      T2.SEX = 'F';
WITH LatestLab AS (     SELECT          ID,         Date,         UA,         ROW_NUMBER() OVER (PARTITION BY ID ORDER BY Date DESC) AS rn     FROM Laboratory ), NormalUA AS (     SELECT          p.ID,         p.SEX,         ll.UA     FROM Patient p     JOIN LatestLab ll ON p.ID = ll.ID     WHERE ll.rn = 1       AND (           (p.SEX = 'M' AND ll.UA < 8.0)           OR           (p.SEX = 'F' AND ll.UA < 6.5)       ) ) SELECT AVG(UA) AS avg_ua FROM NormalUA;
SELECT DISTINCT p.ID, p.SEX, p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.UN = 29;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE p.Diagnosis = 'RA'   AND l.UN < 30;
SELECT COUNT(*) FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.CRE >= 1.5;
SELECT      CASE          WHEN SUM(CASE WHEN p.SEX = 'M' THEN 1 ELSE 0 END) > SUM(CASE WHEN p.SEX = 'F' THEN 1 ELSE 0 END)          THEN 'True'          ELSE 'False'      END AS result FROM      Laboratory l JOIN      Patient p ON l.ID = p.ID WHERE      l.CRE >= 1.5;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.`T-BIL` = (     SELECT MAX(`T-BIL`)     FROM Laboratory     WHERE `T-BIL` IS NOT NULL );
SELECT      p.SEX,     GROUP_CONCAT(DISTINCT p.ID) AS patient_ids FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.`T-BIL` >= 2.0 GROUP BY      p.SEX;
SELECT      p.ID,     l.`T-CHO` FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID ORDER BY      p.Birthday ASC,     l.`T-CHO` DESC LIMIT 1;
SELECT   CAST(SUM(CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER)) AS REAL) * 1.0 / COUNT(p.ID) AS average_age FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.`T-CHO` >= 250;
SELECT DISTINCT     p.ID,     p.Diagnosis FROM Patient p JOIN Laboratory l     ON p.ID = l.ID WHERE l.TG > 300;
SELECT COUNT(DISTINCT T1.ID) FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T2.TG >= 200   AND (strftime('%Y', 'now') - strftime('%Y', T1.Birthday)) > 50;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.CPK < 250;
SELECT COUNT(DISTINCT p.ID) AS male_patients_with_high_cpk FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND strftime('%Y', p.Birthday) BETWEEN '1936' AND '1956'   AND l.CPK >= 250;
SELECT     p.ID,     p.SEX,     (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) AS age FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.GLU >= 180   AND l.`T-CHO` < 250;
SELECT     p.ID,     l.GLU FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     strftime('%Y', p.Description) = '1991'     AND l.GLU < 180;
SELECT      p.ID,     p.SEX,     p.Birthday FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.WBC <= 3.5 OR l.WBC >= 9.0 ORDER BY      p.SEX,     p.Birthday ASC;
SELECT     p.ID,     p.Diagnosis,     CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.RBC < 3.5;
SELECT      p.ID,     p.SEX,     p.Birthday,     p.Admission,     l.RBC FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      p.SEX = 'F'     AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) >= 50     AND (l.RBC <= 3.5 OR l.RBC >= 6.0);
SELECT DISTINCT     p.ID,     p.SEX FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE p.Admission = '-'   AND l.HGB < 10;
SELECT     p.ID,     p.SEX FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     p.Diagnosis = 'SLE'     AND l.HGB > 10     AND l.HGB < 17 ORDER BY     p.Birthday ASC LIMIT 1;
SELECT     p.ID,     (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) AS age FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.HCT >= 52 GROUP BY p.ID HAVING COUNT(l.ID) > 2;
SELECT AVG(HCT) FROM Laboratory WHERE Date LIKE '1991%' AND HCT < 29;
SELECT      SUM(CASE WHEN PLT < 100 THEN 1 ELSE 0 END) - SUM(CASE WHEN PLT > 400 THEN 1 ELSE 0 END) AS difference FROM Laboratory WHERE PLT <= 100 OR PLT >= 400;
SELECT DISTINCT     p.ID FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     strftime('%Y', l.Date) = '1984'     AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) < 50     AND l.PLT BETWEEN 100 AND 400;
SELECT      CAST(SUM(CASE WHEN L.PT >= 14 AND P.SEX = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 /      NULLIF(SUM(CASE WHEN L.PT >= 14 THEN 1 ELSE 0 END), 0) AS percentage FROM Patient P JOIN Laboratory L ON P.ID = L.ID WHERE (strftime('%Y', 'now') - strftime('%Y', P.Birthday)) > 55;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE strftime('%Y', p.`First Date`) > '1992'   AND l.PT < 14;
SELECT COUNT(*) AS count FROM Examination WHERE `Examination Date` > '1997-01-01'   AND APTT < 45;
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l ON e.ID = l.ID WHERE l.APTT > 45   AND e.Thrombosis = 0;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.WBC > 3.5   AND l.WBC < 9.0   AND (l.FG <= 150 OR l.FG >= 450);
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday > '1980-01-01'   AND (l.FG < 150 OR l.FG > 450);
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.`U-PRO` >= 30;
SELECT   p.ID FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.`U-PRO` > 0   AND l.`U-PRO` < 30   AND p.Diagnosis = 'SLE';
SELECT COUNT(DISTINCT ID) FROM Laboratory WHERE IGG >= 2000;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID JOIN Examination e ON p.ID = e.ID WHERE l.IGG > 900   AND l.IGG < 2000   AND e.Symptoms IS NOT NULL;
SELECT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.IGA BETWEEN 80 AND 500 ORDER BY l.IGA DESC LIMIT 1;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.IGA > 80   AND l.IGA < 500   AND p.`First Date` IS NOT NULL   AND strftime('%Y', p.`First Date`) >= '1990';
WITH AbnormalPatients AS (     SELECT DISTINCT         l.ID AS PatientID     FROM Laboratory l     WHERE l.IGM <= 40        OR l.IGM >= 400 ), PatientDiagnosis AS (     SELECT         p.ID AS PatientID,         p.Diagnosis     FROM Patient p     INNER JOIN AbnormalPatients ap         ON p.ID = ap.PatientID     WHERE p.Diagnosis IS NOT NULL ), DiagnosisCounts AS (     SELECT         Diagnosis,         COUNT(*) AS DiagnosisCount     FROM PatientDiagnosis     GROUP BY Diagnosis ) SELECT     Diagnosis FROM DiagnosisCounts ORDER BY DiagnosisCount DESC, Diagnosis ASC LIMIT 1;
SELECT COUNT(*) AS count FROM Patient WHERE Description IS NULL   AND EXISTS (     SELECT 1     FROM Laboratory     WHERE Laboratory.ID = Patient.ID       AND Laboratory.CRP = '+'   );
SELECT COUNT(DISTINCT p.ID) FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.CRE >= 1.5   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) < 70;
SELECT COUNT(DISTINCT e.ID) AS patient_count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE e.KCT = '+'   AND l.RA IN ('-', '+-');
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday >= '1985-01-01'   AND l.RA IN ('-', '+-');
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.RF < 20   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) > 60;
SELECT COUNT(DISTINCT e.ID) AS patient_count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.RF < 20   AND e.Thrombosis = 0;
SELECT COUNT(DISTINCT e.ID) AS patient_count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.C3 > 35   AND e.`ANA Pattern` = 'P';
SELECT     e.ID FROM Examination AS e JOIN Laboratory AS l     ON e.ID = l.ID WHERE l.HCT <= 29    OR l.HCT >= 52 ORDER BY e.`aCL IgA` DESC LIMIT 1;
SELECT COUNT(DISTINCT e.ID) FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE e.Diagnosis = 'APS'   AND l.C4 > 10;
SELECT   COUNT(DISTINCT p.ID) AS patient_count FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.Admission = '+'   AND l.RNP IN ('-', '+-');
SELECT     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.RNP NOT IN ('-', '+-') ORDER BY p.Birthday DESC LIMIT 1;
SELECT COUNT(*) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.SM IN ('-', '+-')   AND e.Thrombosis = 0;
SELECT   p.ID FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.SM NOT IN ('negative', '0') ORDER BY p.Birthday DESC LIMIT 3;
SELECT DISTINCT e.ID FROM Examination e JOIN Laboratory l ON e.ID = l.ID WHERE e.`Examination Date` > '1997-01-01'   AND l.SC170 IN ('negative', '0');
SELECT     COUNT(DISTINCT p.ID) AS count FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     l.SC170 IN ('negative', '0')     AND p.SEX = 'F'     AND NOT EXISTS (         SELECT 1         FROM Examination e         WHERE e.ID = p.ID           AND e.Symptoms IS NOT NULL     );
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.SSA IN ('-', '+-')   AND p.`First Date` IS NOT NULL   AND strftime('%Y', p.`First Date`) < '2000';
SELECT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.SSA NOT IN ('negative', '0') ORDER BY p.`First Date` ASC LIMIT 1;
SELECT COUNT(DISTINCT e.ID) AS patient_count FROM Examination e WHERE e.Diagnosis = 'SLE'   AND e.SSB IN ('-', '+-');
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.SSB IN ('negative', '0')   AND e.Symptoms IS NOT NULL;
SELECT COUNT(DISTINCT p.ID) AS male_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.CENTROMEA IN ('-', '+-')   AND l.SSB IN ('-', '+-')   AND p.SEX = 'M';
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.DNA >= 8;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.DNA < 8   AND p.Description IS NULL;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.IGG > 900   AND l.IGG < 2000   AND p.Admission = '+';
SELECT      CAST(COUNT(CASE WHEN l.GOT >= 60 AND p.Diagnosis = 'SLE' THEN l.ID END) AS REAL) * 100.0 /      COUNT(CASE WHEN l.GOT >= 60 THEN l.ID END) AS percentage FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE l.GOT >= 60;
SELECT COUNT(*) FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.GOT < 60;
SELECT MIN(p.Birthday) AS youngest_birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.GOT >= 60;
SELECT     p."Birthday" FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     l."GPT" < 60 ORDER BY     l."GPT" DESC LIMIT 3;
SELECT COUNT(*) AS male_count FROM Patient WHERE SEX = 'M'   AND EXISTS (     SELECT 1     FROM Laboratory     WHERE Laboratory.ID = Patient.ID       AND Laboratory.GOT < 60   );
WITH NormalLDH AS (     SELECT          l.ID,         l.LDH,         p."First Date"     FROM Laboratory l     JOIN Patient p ON l.ID = p.ID     WHERE l.LDH < 500 ), MaxLDH AS (     SELECT          ID,         "First Date"     FROM NormalLDH     ORDER BY LDH DESC     LIMIT 1 ) SELECT      "First Date" FROM MaxLDH;
SELECT MAX(l.Date) FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.ID = (     SELECT ID     FROM Patient     WHERE "First Date" IS NOT NULL     ORDER BY "First Date" DESC     LIMIT 1 ) AND l.LDH >= 500;
SELECT COUNT(DISTINCT p.ID) AS admitted_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.ALP >= 300   AND p.Admission = '+';
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.ALP < 300;
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TP < 6.0;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Diagnosis = 'SJS'   AND l.TP > 6.0   AND l.TP < 8.5;
SELECT     e.`Examination Date` FROM Examination AS e JOIN Laboratory AS l     ON e.ID = l.ID WHERE l.ALB > 3.5   AND l.ALB < 5.5 ORDER BY l.ALB DESC LIMIT 1;
SELECT COUNT(*) FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.ALB > 3.5   AND l.ALB < 5.5   AND l.TP BETWEEN 6.0 AND 8.5;
SELECT     e.`aCL IgG`,     e.`aCL IgM`,     e.`aCL IgA` FROM Examination AS e JOIN Patient AS p     ON e.ID = p.ID JOIN Laboratory AS l     ON e.ID = l.ID WHERE     p.SEX = 'F'     AND l.UA > 6.50 ORDER BY     l.UA DESC LIMIT 1;
SELECT MAX(e.ANA) AS highest_ana FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.CRE < 1.5;
SELECT     e.ID FROM Examination AS e JOIN Laboratory AS l     ON e.ID = l.ID WHERE l.CRE < 1.5 ORDER BY     e.`aCL IgA` DESC LIMIT 1;
SELECT COUNT(DISTINCT T1.ID) AS count FROM Patient AS T1 INNER JOIN Laboratory AS T2   ON T1.ID = T2.ID INNER JOIN Examination AS T3   ON T1.ID = T3.ID WHERE T2.`T-BIL` >= 2.0   AND T3.`ANA Pattern` LIKE '%P%';
SELECT e.ANA FROM Examination e JOIN Laboratory l ON e.ID = l.ID WHERE l.`T-BIL` < 2.0 ORDER BY l.`T-BIL` DESC LIMIT 1;
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l ON e.ID = l.ID WHERE l.`T-CHO` >= 250   AND e.`KCT` = '-';
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.`T-CHO` < 250   AND e.`ANA Pattern` = 'P';
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID JOIN Examination e ON p.ID = e.ID WHERE l.TG < 200   AND e.Symptoms IS NOT NULL;
SELECT     p.Diagnosis FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     l.TG < 200 ORDER BY     l.TG DESC LIMIT 1;
SELECT DISTINCT e.ID FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE e.Thrombosis = 0   AND l.CPK < 250;
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.CPK < 250   AND (e.KCT = '+' OR e.RVVT = '+' OR e.LAC = '+');
SELECT p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.GLU > 180 ORDER BY p.Birthday ASC LIMIT 1;
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.GLU < 180   AND e.Thrombosis = 0;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '+'   AND l.WBC BETWEEN 3.5 AND 9.0;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Diagnosis = 'SLE'   AND l.WBC BETWEEN 3.5 AND 9.0;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND (l.RBC <= 3.5 OR l.RBC >= 6.0);
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.PLT > 100   AND l.PLT < 400   AND p.Diagnosis IS NOT NULL;
SELECT     l.PLT FROM Laboratory AS l JOIN Patient AS p     ON l.ID = p.ID WHERE     p.Diagnosis = 'MCTD'     AND l.PLT > 100     AND l.PLT < 400;
SELECT AVG(l.PT) AS average_prothrombin_time FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE p.SEX = 'M'   AND l.PT < 14;
SELECT COUNT(DISTINCT e.ID) AS patient_count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE e.Thrombosis IN (1, 2)   AND l.PT < 14;
SELECT m.major_name FROM member mem JOIN major m ON mem.link_to_major = m.major_id WHERE mem.first_name = 'Angela'   AND mem.last_name = 'Sanders';
SELECT COUNT(*) AS student_count FROM member m JOIN major ma ON m.link_to_major = ma.major_id WHERE ma.college = 'College of Engineering';
SELECT     m.first_name,     m.last_name FROM member AS m JOIN major AS mj     ON m.link_to_major = mj.major_id WHERE mj.department = 'Art and Design';
SELECT COUNT(DISTINCT a.link_to_member) AS student_count FROM attendance a JOIN event e ON a.link_to_event = e.event_id JOIN member m ON a.link_to_member = m.member_id WHERE e.event_name = 'Women''s Soccer'   AND m.position = 'Student_Club';
SELECT DISTINCT m.phone FROM member m JOIN attendance a ON m.member_id = a.link_to_member JOIN event e ON a.link_to_event = e.event_id WHERE e.event_name = 'Women''s Soccer';
SELECT COUNT(*) AS count FROM member m JOIN attendance a ON m.member_id = a.link_to_member JOIN event e ON a.link_to_event = e.event_id WHERE e.event_name = 'Women''s Soccer'   AND m.t_shirt_size = 'Medium';
SELECT e.event_name FROM event e JOIN attendance a ON e.event_id = a.link_to_event JOIN member m ON a.link_to_member = m.member_id WHERE m.position = 'Student_Club' GROUP BY e.event_id ORDER BY COUNT(a.link_to_event) DESC LIMIT 1;
SELECT m.college FROM member mem JOIN major m ON mem.link_to_major = m.major_id WHERE mem.position = 'Vice President';
SELECT DISTINCT e.event_name FROM event e JOIN attendance a ON e.event_id = a.link_to_event JOIN member m ON a.link_to_member = m.member_id WHERE m.first_name = 'Maya'   AND m.last_name = 'Mclean';
SELECT COUNT(*) FROM event e JOIN attendance a ON e.event_id = a.link_to_event JOIN member m ON a.link_to_member = m.member_id WHERE e.type = 'Student_Club'   AND m.first_name = 'Sacha'   AND m.last_name = 'Harrison'   AND strftime('%Y', e.event_date) = '2019';
SELECT COUNT(*) AS meeting_count FROM (     SELECT e.event_id     FROM event e     JOIN attendance a ON e.event_id = a.link_to_event     GROUP BY e.event_id     HAVING COUNT(a.link_to_member) > 10 ) AS attended_events JOIN event e ON attended_events.event_id = e.event_id WHERE e.type = 'Meeting';
SELECT e.event_name FROM event e JOIN attendance a ON e.event_id = a.link_to_event WHERE e.type <> 'Fundraiser' GROUP BY e.event_id, e.event_name HAVING COUNT(e.event_id) > 20;
SELECT   CAST(COUNT(e.event_id) AS REAL) / COUNT(DISTINCT e.event_name) AS average_attendance FROM event e JOIN attendance a   ON e.event_id = a.link_to_event WHERE e.type = 'Meeting'   AND strftime('%Y', e.event_date) = '2020';
SELECT expense_description FROM expense ORDER BY cost DESC LIMIT 1;
SELECT COUNT(*) AS member_count FROM member m JOIN major ma ON m.link_to_major = ma.major_id WHERE ma.major_name = 'Environmental Engineering';
SELECT DISTINCT     m.first_name,     m.last_name FROM member m JOIN attendance a     ON m.member_id = a.link_to_member JOIN event e     ON a.link_to_event = e.event_id WHERE e.event_name = 'Laugh Out Loud';
SELECT m.last_name FROM member m JOIN major ma ON m.link_to_major = ma.major_id WHERE ma.major_name = 'Law and Constitutional Studies';
SELECT z.county FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Sherri' AND m.last_name = 'Ramsey';
SELECT m.college FROM member mem JOIN major m ON mem.link_to_major = m.major_id WHERE mem.first_name = 'Tyler' AND mem.last_name = 'Hewitt';
SELECT i.amount FROM income i JOIN member m ON i.link_to_member = m.member_id WHERE m.position = 'Vice President';
SELECT     SUM(b.spent) AS total_spent FROM budget b JOIN event e     ON b.link_to_event = e.event_id WHERE     e.event_name = 'September Meeting'     AND b.category = 'Food';
SELECT z.city, z.state FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.position = 'President';
SELECT DISTINCT     m.first_name,     m.last_name FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE z.state = 'Illinois';
SELECT     b.spent FROM budget AS b JOIN event AS e   ON b.link_to_event = e.event_id WHERE     e.event_name = 'September Meeting'     AND b.category = 'Advertisement';
SELECT DISTINCT m.department FROM major m JOIN member mem ON m.major_id = mem.link_to_major WHERE mem.first_name = 'Pierce'    OR mem.last_name = 'Guidi';
SELECT SUM(b.amount) AS total_budgeted_amount FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'October Speaker';
SELECT e.expense_id, e.expense_description, e.expense_date, e.cost, e.approved FROM expense e JOIN budget b ON e.link_to_budget = b.budget_id JOIN event ev ON b.link_to_event = ev.event_id WHERE ev.event_name = 'October Meeting'   AND ev.event_date = '2019-10-08';
SELECT AVG(e.cost) AS total_average_cost FROM expense e JOIN member m ON e.link_to_member = m.member_id WHERE m.first_name = 'Elijah'   AND m.last_name = 'Allen'   AND (     CAST(SUBSTR(e.expense_date, 6, 2) AS INTEGER) = 9     OR CAST(SUBSTR(e.expense_date, 6, 2) AS INTEGER) = 10   );
SELECT      SUM(CASE WHEN SUBSTR(e.event_date, 1, 4) = '2019' THEN b.spent ELSE 0 END) -     SUM(CASE WHEN SUBSTR(e.event_date, 1, 4) = '2020' THEN b.spent ELSE 0 END) AS difference FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.type = 'Student_Club';
SELECT location FROM event WHERE event_name = 'Spring Budget Review';
SELECT e.cost FROM expense e JOIN event ev ON e.link_to_budget = (     SELECT b.budget_id     FROM budget b     WHERE b.link_to_event = ev.event_id ) WHERE e.expense_description = 'Posters'   AND ev.event_date = '2019-09-04';
SELECT     b.remaining FROM     budget b WHERE     b.category = 'Food'     AND b.amount = (         SELECT             MAX(b2.amount)         FROM             budget b2         WHERE             b2.category = 'Food'     );
SELECT notes FROM income WHERE source = 'Fundraising'   AND date_received = '2019-09-14';
SELECT COUNT(*) AS major_count FROM major WHERE college = 'College of Humanities and Social Sciences';
SELECT phone FROM member WHERE first_name = 'Carlo'   AND last_name = 'Jacobs';
SELECT z.county FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Adela' AND m.last_name = 'O''Gallagher';
SELECT COUNT(*) AS exceeded_budget_count FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'November Meeting'   AND b.remaining < 0;
SELECT SUM(b.amount) AS total_budget_amount FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'September Speaker';
SELECT     b.event_status FROM expense AS e JOIN budget AS b     ON e.link_to_budget = b.budget_id WHERE     e.expense_description = 'Post Cards, Posters'     AND e.expense_date = '2019-8-20';
SELECT m.major_name FROM member mem JOIN major m ON mem.link_to_major = m.major_id WHERE mem.first_name = 'Brent'   AND mem.last_name = 'Thomason';
SELECT COUNT(*) AS count FROM member m JOIN major ma ON m.link_to_major = ma.major_id WHERE ma.major_name = 'Business'   AND m.t_shirt_size = 'Medium';
SELECT z.type FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Christof' AND m.last_name = 'Nielson';
SELECT m.major_name FROM member mem JOIN major m ON mem.link_to_major = m.major_id WHERE mem.position = 'Vice President';
SELECT z.state FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Sacha' AND m.last_name = 'Harrison';
SELECT m.department FROM member AS mem JOIN major AS m ON mem.link_to_major = m.major_id WHERE mem.position = 'President';
SELECT i.date_received FROM income i JOIN member m ON i.link_to_member = m.member_id WHERE m.first_name = 'Connor'   AND m.last_name = 'Hilton'   AND i.source = 'Dues';
SELECT      m.first_name,     m.last_name FROM income i JOIN member m ON i.link_to_member = m.member_id WHERE i.source = 'Dues' ORDER BY i.date_received ASC LIMIT 1;
SELECT     SUM(CASE WHEN e.event_name = 'Yearly Kickoff' THEN b.amount ELSE 0 END) * 1.0 /     SUM(CASE WHEN e.event_name = 'October Meeting' THEN b.amount ELSE 0 END) AS ratio FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE b.category = 'Advertisement';
SELECT      CAST(SUM(CASE WHEN b.category = 'Parking' THEN b.amount ELSE 0 END) AS REAL) * 100 /      SUM(b.amount) AS percentage FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'November Speaker';
SELECT SUM(e.cost) AS total_cost FROM expense e JOIN budget b ON e.link_to_budget = b.budget_id JOIN event ev ON b.link_to_event = ev.event_id WHERE e.expense_description = 'Pizza';
SELECT COUNT(DISTINCT city) AS city_count FROM zip_code WHERE county = 'Orange County'   AND state = 'Virginia';
SELECT DISTINCT department FROM major WHERE college = 'College of Humanities and Social Sciences';
SELECT z.city, z.county, z.state FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Amy' AND m.last_name = 'Firth';
SELECT     e.expense_description FROM expense AS e JOIN budget AS b     ON e.link_to_budget = b.budget_id WHERE b.remaining = (     SELECT MIN(remaining)     FROM budget );
