WITH member_event_expenses AS (     SELECT         e.link_to_member,         b.link_to_event,         e.cost     FROM expense e     JOIN budget b ON e.link_to_budget = b.budget_id ), members_with_multiple_events AS (     SELECT         link_to_member     FROM member_event_expenses     GROUP BY link_to_member     HAVING COUNT(DISTINCT link_to_event) > 1 ) SELECT     m.first_name,     m.last_name,     MAX(mee.cost) AS max_cost FROM member m JOIN member_event_expenses mee ON m.member_id = mee.link_to_member JOIN members_with_multiple_events mwme ON m.member_id = mwme.link_to_member GROUP BY m.member_id ORDER BY max_cost DESC LIMIT 1;
SELECT   SUM(e.cost) * 1.0 / COUNT(ev.event_id) AS average_amount_paid FROM expense e JOIN member m   ON e.link_to_member = m.member_id JOIN attendance a   ON m.member_id = a.link_to_member JOIN event ev   ON a.link_to_event = ev.event_id WHERE m.position <> 'Member';
SELECT e.event_name FROM event e JOIN budget b ON e.event_id = b.link_to_event JOIN expense ex ON b.budget_id = ex.link_to_budget WHERE b.category = 'Parking'   AND ex.cost < (     SELECT SUM(ex2.cost) * 1.0 / COUNT(DISTINCT e2.event_id)     FROM event e2     JOIN budget b2 ON e2.event_id = b2.link_to_event     JOIN expense ex2 ON b2.budget_id = ex2.link_to_budget     WHERE b2.category = 'Parking'   );
SELECT   CAST(SUM(e.cost) AS REAL) * 100 / COUNT(ev.event_id) AS percentage FROM expense e JOIN budget b   ON e.link_to_budget = b.budget_id JOIN event ev   ON b.link_to_event = ev.event_id WHERE ev.type = 'Meeting';
