SELECT COUNT(*) AS count FROM gasstations WHERE Country = 'CZE' AND Segment = 'Premium';
SELECT      CAST(SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS REAL) /      NULLIF(SUM(CASE WHEN Currency = 'CZK' THEN 1 ELSE 0 END), 0) AS ratio FROM customers;
SELECT     c.CustomerID FROM yearmonth AS ym JOIN customers AS c     ON ym.CustomerID = c.CustomerID WHERE     c.Segment = 'LAM'     AND ym.Date BETWEEN '201201' AND '201212' ORDER BY     ym.Consumption ASC LIMIT 1;
SELECT     AVG(ym.Consumption) / 12 AS average_monthly_consumption FROM yearmonth AS ym JOIN customers AS c     ON ym.CustomerID = c.CustomerID WHERE c.Segment = 'SME'   AND ym.Date BETWEEN '201301' AND '201312';
SELECT     c.CustomerID FROM customers c JOIN yearmonth ym     ON c.CustomerID = ym.CustomerID WHERE     c.Currency = 'CZK'     AND ym.Date BETWEEN '201101' AND '201112' ORDER BY     ym.Consumption DESC LIMIT 1;
SELECT COUNT(DISTINCT c.CustomerID) AS customer_count FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Segment = 'KAM'   AND ym.Date BETWEEN '201201' AND '201212'   AND ym.Consumption < 30000;
WITH c AS (     SELECT         SUM(CASE WHEN c.Currency = 'CZK' THEN ym.Consumption ELSE 0 END) AS czk_total,         SUM(CASE WHEN c.Currency = 'EUR' THEN ym.Consumption ELSE 0 END) AS eur_total     FROM yearmonth ym     JOIN customers c ON ym.CustomerID = c.CustomerID     WHERE ym.Date BETWEEN '201201' AND '201212' ) SELECT czk_total - eur_total AS difference FROM c;
SELECT     strftime('%Y', t.Date) AS Year FROM     transactions_1k t JOIN     customers c ON t.CustomerID = c.CustomerID WHERE     c.Currency = 'EUR' GROUP BY     strftime('%Y', t.Date) ORDER BY     SUM(t.Amount) DESC LIMIT 1;
SELECT     c.Segment FROM customers c JOIN yearmonth ym     ON c.CustomerID = ym.CustomerID GROUP BY     c.Segment ORDER BY     SUM(ym.Consumption) ASC LIMIT 1;
SELECT     SUBSTR(ym.Date, 1, 4) AS Year FROM     yearmonth AS ym JOIN     customers AS c     ON ym.CustomerID = c.CustomerID WHERE     c.Currency = 'CZK' GROUP BY     SUBSTR(ym.Date, 1, 4) ORDER BY     SUM(ym.Consumption) DESC LIMIT 1;
WITH sme_customers AS (     SELECT CustomerID     FROM customers     WHERE Segment = 'SME' ), monthly_consumption AS (     SELECT          ym.CustomerID,         ym.Date,         ym.Consumption     FROM yearmonth ym     INNER JOIN sme_customers sc ON ym.CustomerID = sc.CustomerID     WHERE ym.Date BETWEEN '201301' AND '201312' ), monthly_totals AS (     SELECT          Date,         SUM(Consumption) AS TotalConsumption     FROM monthly_consumption     GROUP BY Date ) SELECT Date FROM monthly_totals ORDER BY TotalConsumption DESC LIMIT 1;
WITH cze_customers AS (     SELECT          c.CustomerID,         c.Segment     FROM customers c     WHERE c.Currency = 'CZK' ), customer_consumption_2013 AS (     SELECT          cc.CustomerID,         cc.Segment,         SUM(ym.Consumption) AS total_consumption     FROM cze_customers cc     JOIN yearmonth ym ON cc.CustomerID = ym.CustomerID     WHERE ym.Date BETWEEN '201301' AND '201312'     GROUP BY cc.CustomerID, cc.Segment ), lowest_consumption_per_segment AS (     SELECT          Segment,         MIN(total_consumption) AS min_consumption     FROM customer_consumption_2013     GROUP BY Segment ), customers_with_lowest_consumption AS (     SELECT          cc.CustomerID,         cc.Segment,         cc.total_consumption     FROM customer_consumption_2013 cc     JOIN lowest_consumption_per_segment lcs ON cc.Segment = lcs.Segment AND cc.total_consumption = lcs.min_consumption ), segment_annual_average AS (     SELECT          Segment,         AVG(total_consumption) AS annual_average     FROM customers_with_lowest_consumption     GROUP BY Segment ) SELECT      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'SME') -      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'LAM') AS sme_lam_diff,     (SELECT annual_average FROM segment_annual_average WHERE Segment = 'LAM') -      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'KAM') AS lam_kam_diff,     (SELECT annual_average FROM segment_annual_average WHERE Segment = 'KAM') -      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'SME') AS kam_sme_diff
WITH consumption_by_segment_year AS (     SELECT          c.Segment,         CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) AS Year,         SUM(ym.Consumption) AS TotalConsumption     FROM yearmonth ym     JOIN customers c ON ym.CustomerID = c.CustomerID     WHERE c.Currency = 'EUR'       AND c.Segment IN ('SME', 'LAM', 'KAM')       AND CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) IN (2012, 2013)     GROUP BY c.Segment, CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) ), segment_consumption AS (     SELECT          Segment,         SUM(CASE WHEN Year = 2012 THEN TotalConsumption ELSE 0 END) AS Consumption2012,         SUM(CASE WHEN Year = 2013 THEN TotalConsumption ELSE 0 END) AS Consumption2013     FROM consumption_by_segment_year     GROUP BY Segment ), segment_percentage AS (     SELECT          Segment,         (Consumption2013 - Consumption2012) AS IncreaseDecrease,         ((Consumption2013 - Consumption2012) / Consumption2013) * 100 AS PercentageIncrease     FROM segment_consumption     WHERE Consumption2013 != 0 ) SELECT      (SELECT Segment FROM segment_percentage ORDER BY PercentageIncrease DESC LIMIT 1) AS BiggestIncreaseSegment,     (SELECT Segment FROM segment_percentage ORDER BY PercentageIncrease ASC LIMIT 1) AS LowestIncreaseSegment FROM segment_percentage LIMIT 1;
SELECT SUM(Consumption) AS total_consumption FROM yearmonth WHERE CustomerID = 6   AND Date BETWEEN '201308' AND '201311';
SELECT      (SELECT COUNT(*) FROM gasstations WHERE Country = 'CZE' AND Segment = 'Discount') -     (SELECT COUNT(*) FROM gasstations WHERE Country = 'SVK' AND Segment = 'Discount') AS difference;
SELECT      (SELECT Consumption       FROM yearmonth       WHERE CustomerID = 7 AND Date = '201304') -      (SELECT Consumption       FROM yearmonth       WHERE CustomerID = 5 AND Date = '201304') AS difference;
SELECT      (SELECT COUNT(*) FROM customers WHERE Segment = 'SME' AND Currency = 'CZK') -      (SELECT COUNT(*) FROM customers WHERE Segment = 'SME' AND Currency = 'EUR') AS difference
SELECT     c.CustomerID FROM customers AS c JOIN yearmonth AS ym     ON c.CustomerID = ym.CustomerID WHERE     c.Segment = 'LAM'     AND c.Currency = 'EUR'     AND ym.Date = '201310' ORDER BY     ym.Consumption DESC LIMIT 1;
SELECT      c.CustomerID,     SUM(ym.Consumption) AS TotalConsumption FROM      customers c JOIN      yearmonth ym ON c.CustomerID = ym.CustomerID WHERE      c.Segment = 'KAM' GROUP BY      c.CustomerID ORDER BY      TotalConsumption DESC LIMIT 1;
SELECT     SUM(ym.Consumption) AS total_consumption FROM yearmonth AS ym JOIN customers AS c     ON ym.CustomerID = c.CustomerID WHERE     c.Segment = 'KAM'     AND ym.Date = '201305';
SELECT      (         SELECT COUNT(DISTINCT ym.CustomerID)         FROM yearmonth ym         JOIN customers c ON ym.CustomerID = c.CustomerID         WHERE c.Segment = 'LAM'           AND ym.Consumption > 46.73     ) * 100.0 /      (         SELECT COUNT(DISTINCT c.CustomerID)         FROM customers c         WHERE c.Segment = 'LAM'     ) AS percentage
SELECT      gs.Country,     COUNT(*) AS TotalValueForMoneyStations FROM      gasstations gs WHERE      gs.Segment = 'Value for money' GROUP BY      gs.Country ORDER BY      TotalValueForMoneyStations DESC;
SELECT      CAST(SUM(CASE WHEN c.Currency = 'EUR' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM      customers c WHERE      c.Segment = 'KAM';
WITH feb_2012 AS (     SELECT         CustomerID,         Consumption     FROM         yearmonth     WHERE         Date = '201202' ), total_customers AS (     SELECT         COUNT(*) AS total     FROM         feb_2012 ), above_threshold AS (     SELECT         COUNT(*) AS above     FROM         feb_2012     WHERE         Consumption > 528.3 ) SELECT     CAST(above.above AS REAL) * 100 / total.total AS percentage FROM     above_threshold above CROSS JOIN     total_customers total;
SELECT      CAST(SUM(CASE WHEN gs.Segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM gasstations gs WHERE gs.Country = 'SVK';
SELECT CustomerID FROM yearmonth WHERE Date = '201309' ORDER BY Consumption DESC LIMIT 1;
SELECT     c.Segment FROM     yearmonth y JOIN     customers c     ON y.CustomerID = c.CustomerID WHERE     y.Date = '201309' GROUP BY     c.Segment ORDER BY     SUM(y.Consumption) ASC LIMIT 1;
SELECT c.CustomerID FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Segment = 'SME'   AND ym.Date = '201206' ORDER BY ym.Consumption ASC LIMIT 1;
SELECT MAX(Consumption) AS highest_monthly_consumption FROM yearmonth WHERE substr(Date, 1, 4) = '2012';
WITH euro_customers AS (     SELECT CustomerID     FROM customers     WHERE Currency = 'EUR' ), monthly_consumption AS (     SELECT          ym.CustomerID,         SUM(ym.Consumption) / 12.0 AS monthly_consumption     FROM yearmonth ym     INNER JOIN euro_customers ec ON ym.CustomerID = ec.CustomerID     GROUP BY ym.CustomerID ) SELECT MAX(monthly_consumption) AS biggest_monthly_consumption FROM monthly_consumption;
SELECT DISTINCT p.Description FROM products p JOIN transactions_1k t ON p.ProductID = t.ProductID WHERE strftime('%Y%m', t.Date) = '201309';
SELECT DISTINCT gs.Country FROM gasstations gs JOIN transactions_1k t ON gs.GasStationID = t.GasStationID WHERE strftime('%Y%m', t.Date) = '201306';
SELECT DISTINCT gs.ChainID FROM gasstations gs JOIN transactions_1k t ON gs.GasStationID = t.GasStationID JOIN customers c ON t.CustomerID = c.CustomerID WHERE c.Currency = 'EUR';
SELECT DISTINCT p.Description FROM products p JOIN transactions_1k t ON p.ProductID = t.ProductID JOIN customers c ON t.CustomerID = c.CustomerID WHERE c.Currency = 'EUR';
SELECT AVG(Price) AS average_total_price FROM transactions_1k WHERE Date LIKE '2012-01%';
SELECT COUNT(DISTINCT c.CustomerID) AS customer_count FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Currency = 'EUR'   AND ym.Consumption > 1000;
SELECT DISTINCT p.Description FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID JOIN products p ON t.ProductID = p.ProductID WHERE g.Country = 'CZE';
SELECT DISTINCT t.Time FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.ChainID = 11;
SELECT COUNT(*) FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.Country = 'CZE'   AND t.Price > 1000;
SELECT COUNT(*) FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.Country = 'CZE'   AND t.Date > '2012-01-01';
SELECT AVG(t.Price) AS average_total_price FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.Country = 'CZE';
SELECT AVG(t.Price) AS average_total_price FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE c.Currency = 'EUR';
SELECT c.CustomerID FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE t.Date = '2012-08-25' ORDER BY t.Amount DESC LIMIT 1;
SELECT gs.Country FROM transactions_1k t JOIN gasstations gs ON t.GasStationID = gs.GasStationID WHERE t.Date = '2012-08-25' ORDER BY t.TransactionID ASC LIMIT 1;
SELECT DISTINCT c.Currency FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE t.Date = '2012-08-24'   AND t.Time = '16:25:00';
SELECT c.Segment FROM customers c JOIN transactions_1k t ON c.CustomerID = t.CustomerID WHERE t.Date = '2012-08-23'   AND t.Time = '21:20:00';
SELECT COUNT(*) AS transaction_count FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE t.Date = '2012-08-26'   AND t.Time < '13:00:00'   AND c.Currency = 'CZK';
SELECT c.Segment FROM customers c ORDER BY c.CustomerID ASC LIMIT 1;
SELECT     gs.Country FROM     transactions_1k AS t JOIN     gasstations AS gs     ON t.GasStationID = gs.GasStationID WHERE     t.Date = '2012-08-24'     AND t.Time = '12:42:00';
SELECT ProductID FROM transactions_1k WHERE Date = '2012-08-23'   AND Time = '21:20:00';
WITH target_customer AS (     SELECT         t.CustomerID     FROM         transactions_1k t     WHERE         t.Date = '2012-08-24'         AND t.Price = 124.05 ), jan_2012_transactions AS (     SELECT         t.Date,         t.Price     FROM         transactions_1k t     JOIN         target_customer tc     ON         t.CustomerID = tc.CustomerID     WHERE         t.Date LIKE '2012-01-%' ) SELECT     SUM(j.Price) AS total_spent,     j.Date,     j.Price AS expense FROM     jan_2012_transactions j ORDER BY     j.Date;
SELECT COUNT(*) AS transaction_count FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE t.Date = '2012-08-26'   AND t.Time BETWEEN '08:00:00' AND '09:00:00'   AND g.Country = 'CZE';
SELECT c.Currency FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE ym.Date LIKE '%201306%'   AND ym.Consumption = 214582.17;
SELECT gs.Country FROM transactions_1k t JOIN gasstations gs ON t.GasStationID = gs.GasStationID WHERE t.CardID = 667467 LIMIT 1;
SELECT c.Currency FROM customers c JOIN transactions_1k t ON c.CustomerID = t.CustomerID WHERE t.Date = '2012-08-24'   AND t.Price = 548.4;
WITH customers_on_date AS (     SELECT DISTINCT         t.CustomerID,         c.Currency     FROM transactions_1k t     JOIN customers c ON t.CustomerID = c.CustomerID     WHERE t.Date = '2012-08-25' ), currency_counts AS (     SELECT         COUNT(*) AS total_customers,         SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS eur_customers     FROM customers_on_date ) SELECT     (eur_customers * 100.0) / total_customers AS percentage FROM currency_counts;
WITH target_customer AS (     SELECT         t.CustomerID     FROM transactions_1k t     WHERE t.Date = '2012-08-25'       AND t.Price = 634.8 ), consumption_by_year AS (     SELECT         ym.CustomerID,         SUM(CASE WHEN ym.Date LIKE '2012%' THEN ym.Consumption ELSE 0 END) AS consumption_2012,         SUM(CASE WHEN ym.Date LIKE '2013%' THEN ym.Consumption ELSE 0 END) AS consumption_2013     FROM yearmonth ym     WHERE ym.CustomerID IN (SELECT CustomerID FROM target_customer)     GROUP BY ym.CustomerID ) SELECT     (consumption_2012 - consumption_2013) / consumption_2012 AS consumption_decrease_rate FROM consumption_by_year;
SELECT gs.GasStationID FROM gasstations gs JOIN transactions_1k t ON gs.GasStationID = t.GasStationID GROUP BY gs.GasStationID ORDER BY SUM(t.Amount) DESC LIMIT 1;
SELECT   CAST(SUM(CASE WHEN gs.Segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM gasstations gs WHERE gs.Country = 'SVK';
SELECT     SUM(t.Amount) AS total_amount,     COALESCE(SUM(CASE WHEN ym.Date = '201201' THEN ym.Consumption ELSE 0 END), 0) AS jan_2012_spent FROM transactions_1k t LEFT JOIN yearmonth ym     ON t.CustomerID = ym.CustomerID WHERE t.CustomerID = 38508;
SELECT p.Description FROM products p JOIN transactions_1k t ON p.ProductID = t.ProductID GROUP BY p.ProductID, p.Description ORDER BY SUM(t.Amount) DESC LIMIT 5;
WITH top_customer AS (     SELECT          c.CustomerID,         c.Currency,         SUM(t.Price) AS total_price,         SUM(t.Amount) AS total_amount     FROM customers c     JOIN transactions_1k t ON c.CustomerID = t.CustomerID     GROUP BY c.CustomerID, c.Currency     ORDER BY SUM(t.Price) DESC     LIMIT 1 ) SELECT      tc.CustomerID,     tc.total_price / tc.total_amount AS average_price_per_item,     tc.Currency FROM top_customer tc;
SELECT     gs.Country FROM transactions_1k t JOIN gasstations gs     ON t.GasStationID = gs.GasStationID WHERE     t.ProductID = 2 ORDER BY     t.Price DESC LIMIT 1;
WITH high_price_customers AS (     SELECT DISTINCT t.CustomerID     FROM transactions_1k t     WHERE t.ProductID = 5       AND t.Amount > 0       AND (t.Price / t.Amount) > 29.00 ) SELECT ym.Consumption FROM yearmonth ym JOIN high_price_customers hpc ON ym.CustomerID = hpc.CustomerID WHERE ym.Date = '201208';
